// ============================================================
// Client-side JavaScript
// ระบบใบแจ้งซ่อมออนไลน์ - Thai Lion Air
// ============================================================

// === STATE ===
let currentUser = null;
let allRequests = [];
let deleteTarget = null;
let currentDashboardTab = 'requests'; // 'requests' or 'gse_status'

// === INIT ===
document.addEventListener('DOMContentLoaded', function() {
  // ตรวจสอบ session จาก localStorage
  const savedUser = localStorage.getItem('corrective_user');
  if (savedUser) {
    try {
      currentUser = JSON.parse(savedUser);
      showDashboard();
    } catch(e) {
      localStorage.removeItem('corrective_user');
      showPage('loginPage');
    }
  } else {
    showPage('loginPage');
  }
});

// === PAGE NAVIGATION ===
function showPage(pageId) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  const page = document.getElementById(pageId);
  if (page) page.classList.add('active');
}

// === LOADING ===
function showLoading() {
  document.getElementById('loadingOverlay').style.display = 'flex';
}

function hideLoading() {
  document.getElementById('loadingOverlay').style.display = 'none';
}

// === TOAST ===
function showToast(message, type) {
  const toast = document.getElementById('toast');
  const toastMsg = document.getElementById('toastMessage');
  toastMsg.textContent = message;
  toast.className = 'toast' + (type ? ' toast-' + type : '');
  toast.style.display = 'block';
  setTimeout(() => { toast.style.display = 'none'; }, 3000);
}

// === LOGIN ===
function handleLoginInput(input) {
  let val = input.value.toUpperCase().replace(/\s+/g, '');
  if (val.length > 8) val = val.substring(0, 8);
  input.value = val;
  const errorEl = document.getElementById('loginError');
  if (errorEl) {
    errorEl.style.display = 'none';
  }
}

function handleLogin() {
  const inputEl = document.getElementById('loginEmployeeId');
  let employeeId = inputEl.value.trim().toUpperCase().replace(/\s+/g, '');
  inputEl.value = employeeId;
  const errorEl = document.getElementById('loginError');

  if (!employeeId) {
    errorEl.textContent = 'กรุณากรอกรหัสพนักงาน';
    errorEl.style.display = 'block';
    return;
  }

  // บังคับขึ้นต้นด้วย TL เท่านั้น (ห้ามไว้ข้างหลัง เช่น 123456TL)
  if (!employeeId.startsWith('TL')) {
    errorEl.textContent = 'รหัสพนักงานต้องขึ้นต้นด้วย TL นำหน้าเท่านั้น (เช่น TL123456) ไม่อนุญาตให้ใส่ไว้ด้านหลัง';
    errorEl.style.display = 'block';
    return;
  }

  // จำกัดความยาว 8 ตัวอักษรพอดี
  if (employeeId.length !== 8) {
    errorEl.textContent = 'รหัสพนักงานต้องมีความยาว 8 ตัวอักษรพอดี (TL ตามด้วยตัวเลข 6 หลัก เช่น TL123456)';
    errorEl.style.display = 'block';
    return;
  }

  // ตรวจสอบว่าหลังจาก TL เป็นตัวเลข 6 หลัก
  if (!/^TL\d{6}$/.test(employeeId)) {
    errorEl.textContent = 'รหัสพนักงานต้องขึ้นต้นด้วย TL และตามด้วยตัวเลข 6 หลัก (เช่น TL123456)';
    errorEl.style.display = 'block';
    return;
  }

  errorEl.style.display = 'none';
  showLoading();

  google.script.run
    .withSuccessHandler(function(result) {
      hideLoading();
      if (result.success) {
        currentUser = result.user;
        localStorage.setItem('corrective_user', JSON.stringify(currentUser));
        showDashboard();
        showToast('เข้าสู่ระบบสำเร็จ ยินดีต้อนรับ ' + currentUser.fullName, 'success');
      } else {
        errorEl.textContent = result.message;
        errorEl.style.display = 'block';
      }
    })
    .withFailureHandler(function(error) {
      hideLoading();
      errorEl.textContent = 'เกิดข้อผิดพลาด: ' + error.message;
      errorEl.style.display = 'block';
    })
    .login(employeeId);
}

function handleLogout() {
  if (currentUser && currentUser.employeeId) {
    try {
      google.script.run.removeUserHeartbeat(currentUser.employeeId);
    } catch(e) {}
  }
  stopHeartbeat();
  currentUser = null;
  localStorage.removeItem('corrective_user');
  localStorage.removeItem('cached_dashboard_data');
  document.getElementById('loginEmployeeId').value = '';
  document.getElementById('loginError').style.display = 'none';
  const activeNav = document.getElementById('navActiveUsersBadge');
  if (activeNav) activeNav.style.display = 'none';
  const activeTb = document.getElementById('btnActiveUsersToolbar');
  if (activeTb) activeTb.style.display = 'none';
  const restoreWoTb = document.getElementById('btnRestoreWoToolbar');
  if (restoreWoTb) restoreWoTb.style.display = 'none';
  const tabPm = document.getElementById('tabNavPm');
  if (tabPm) tabPm.style.display = 'none';
  showPage('loginPage');
}

// === DASHBOARD ===
function showDashboard() {
  if (!currentUser) return;

  // อัพเดต navbar
  document.getElementById('navUserName').textContent = currentUser.fullName;
  const roleBadge = document.getElementById('navUserRole');
  if (currentUser.role === 'admin') {
    roleBadge.textContent = 'ADMIN';
    roleBadge.style.background = 'rgba(255,193,7,0.3)';
    roleBadge.style.color = '#FFF';
  } else if (currentUser.role === 'manager') {
    roleBadge.textContent = 'MANAGER';
    roleBadge.style.background = '#8B5CF6';
    roleBadge.style.color = '#FFF';
  } else if (currentUser.role === 'supervisor') {
    roleBadge.textContent = 'SUPERVISOR';
    roleBadge.style.background = '#0D9488';
    roleBadge.style.color = '#FFF';
  } else if (currentUser.role === 'technician') {
    roleBadge.textContent = 'TECHNICIAN';
    roleBadge.style.background = '#2563EB';
    roleBadge.style.color = '#FFF';
  } else {
    roleBadge.textContent = 'USER';
    roleBadge.style.background = 'rgba(255,255,255,0.2)';
    roleBadge.style.color = '#FFF';
  }

  // จำกัดการมองเห็นปุ่มตรวจจับผู้ใช้ออนไลน์, ปุ่มกู้คืน W/O และเมนู PM เฉพาะ User Admin เท่านั้น
  const isAdmin = currentUser.role === 'admin';
  const activeNav = document.getElementById('navActiveUsersBadge');
  if (activeNav) activeNav.style.display = isAdmin ? 'inline-flex' : 'none';
  const activeTb = document.getElementById('btnActiveUsersToolbar');
  if (activeTb) activeTb.style.display = isAdmin ? 'inline-flex' : 'none';
  const restoreWoTb = document.getElementById('btnRestoreWoToolbar');
  if (restoreWoTb) restoreWoTb.style.display = isAdmin ? 'inline-flex' : 'none';
  const tabPm = document.getElementById('tabNavPm');
  if (tabPm) tabPm.style.display = isAdmin ? 'inline-flex' : 'none';

  startHeartbeat();

  showPage('dashboardPage');
  if (!isAdmin && currentDashboardTab === 'pm') {
    currentDashboardTab = 'requests';
  }
  switchDashboardTab(currentDashboardTab || 'requests');
  loadDashboardData();

  // Prefetch รูปแบบฟอร์มพิมพ์ในเบื้องหลังเงียบๆ 3.5 วิ หลังจากแดชบอร์ดพร้อม (ไม่บล็อกหน้าจอ)
  setTimeout(function() {
    if (typeof ensurePdfTemplateLoaded === 'function') {
      ensurePdfTemplateLoaded();
    }
  }, 3500);
}

/**
 * ตั้งค่าสถานะการซิงค์ข้อมูลบน Navbar
 */
function setSyncingStatus(isSyncing) {
  var ind = document.getElementById('syncIndicator');
  var icon = document.getElementById('navRefreshIcon');
  if (ind) ind.style.display = isSyncing ? 'inline-flex' : 'none';
  if (icon) {
    if (isSyncing) icon.classList.add('fa-spin');
    else icon.classList.remove('fa-spin');
  }
}

/**
 * บันทึก Cache ลง LocalStorage อย่างปลอดภัย
 */
function saveDashboardToLocalCache(data) {
  if (!data || !currentUser) return;
  try {
    var cachePayload = {
      empId: currentUser.employeeId,
      role: currentUser.role,
      timestamp: Date.now(),
      requests: data.requests || allRequests || [],
      counts: data.counts || null
    };
    localStorage.setItem('cached_dashboard_data', JSON.stringify(cachePayload));
  } catch (e) {
    console.warn('Cannot write to localStorage cache:', e);
  }
}

/**
 * ดึงข้อมูล Dashboard ด้วยเทคนิค SWR (Stale-While-Revalidate)
 * แสดงผลข้อมูลแคชในเครื่องทันที 0ms แล้วซิงค์ข้อมูลล่าสุดกับเซิร์ฟเวอร์แบบเงียบๆ เบื้องหลัง
 */
function loadDashboardData(isManual) {
  if (!currentUser) return;

  var hasCache = false;
  var cachedStr = localStorage.getItem('cached_dashboard_data');
  if (cachedStr && !isManual) {
    try {
      var cached = JSON.parse(cachedStr);
      // ตรวจสอบว่าแคชเป็นของ User ปัจจุบัน
      if (cached && cached.empId === currentUser.employeeId && cached.requests && Array.isArray(cached.requests)) {
        allRequests = cached.requests;
        renderTable(allRequests);
        renderGseDashboard();
        if (typeof renderPmDashboard === 'function' && currentDashboardTab === 'pm') {
          renderPmDashboard();
        }
        recomputeAndUpdateCounts();
        hasCache = true;
      }
    } catch(e) {
      console.warn('Failed to parse cached dashboard:', e);
    }
  }

  // ซิงค์ข้อมูลสดจากเซิร์ฟเวอร์
  // ถ้าไม่มีแคช (เปิดครั้งแรก) ให้แสดง loading spinner
  // ถ้ามีแคชแล้ว ให้ซิงค์เบื้องหลังแบบ Silent Sync (หมุนไอคอนที่ navbar โดยไม่บล็อกหน้าจอ)
  fetchDashboardWithRetry(2, isManual || !hasCache);
}

/**
 * ฟังก์ชันดึงข้อมูลจาก Server พร้อมระบบ Auto-Retry และ Fault Tolerance
 */
function fetchDashboardWithRetry(retriesLeft, showBlockingSpinner) {
  if (!currentUser) return;
  if (showBlockingSpinner) showLoading();
  setSyncingStatus(true);

  google.script.run
    .withSuccessHandler(function(result) {
      if (showBlockingSpinner) hideLoading();
      setSyncingStatus(false);
      if (result && result.requests) {
        allRequests = result.requests;
        renderTable(allRequests);
        renderGseDashboard();
        if (typeof renderPmDashboard === 'function' && currentDashboardTab === 'pm') {
          renderPmDashboard();
        }
        recomputeAndUpdateCounts();
        saveDashboardToLocalCache(result);
      }
    })
    .withFailureHandler(function(error) {
      if (retriesLeft > 0) {
        console.warn('Dashboard fetch failed, retrying in 1.5s...', error);
        setTimeout(function() {
          fetchDashboardWithRetry(retriesLeft - 1, showBlockingSpinner);
        }, 1500);
      } else {
        if (showBlockingSpinner) hideLoading();
        setSyncingStatus(false);
        if (allRequests && allRequests.length > 0) {
          showToast('การเชื่อมต่อไม่เสถียร กำลังแสดงข้อมูลล่าสุดในเครื่อง', 'warning');
        } else {
          showToast('ไม่สามารถโหลดข้อมูลได้: ' + (error ? error.message : 'Unknown error'), 'error');
        }
      }
    })
    .getDashboardData(currentUser.employeeId, currentUser.role);
}

/**
 * ปุ่ม Refresh แบบกดเองบน Navbar
 */
function handleManualRefresh() {
  loadDashboardData(true);
  loadEquipmentMaster(null, true);
  showToast('กำลังซิงค์ข้อมูลล่าสุด...', 'info');
}

/**
 * อัปเดตตัวเลขนับสถานะบน Dashboard โดยไม่ต้องเรียก server ใหม่
 */
function isPmRequest(r) {
  if (!r) return false;
  return (r.Priority === 'PM') || (typeof r.RequestID === 'string' && r.RequestID.indexOf('PM-') === 0);
}

/**
 * อัปเดตตัวเลขนับสถานะบน Dashboard โดยไม่ต้องเรียก server ใหม่
 */
function recomputeAndUpdateCounts() {
  var cmTotal = 0, cmPending = 0, cmInProgress = 0, cmWaitingReview = 0, cmCompleted = 0;
  var pmTotal = 0, pmPending = 0, pmProgress = 0, pmWaitingReview = 0, pmCompleted = 0;

  (allRequests || []).forEach(function(r) {
    var isPm = isPmRequest(r);
    var status = (r.Status || 'รอดำเนินการ').toString().trim();

    if (isPm) {
      pmTotal++;
      if (status === 'กำลังซ่อม') {
        pmProgress++;
      } else if (status === 'รอตรวจสอบ' || status === 'รอ Supervisor ตรวจสอบ' || status === 'รอ Manager อนุมัติ') {
        pmWaitingReview++;
      } else if (status === 'COMPLETE' || status === 'เสร็จสิ้น' || status === 'เสร็จสิ้น (Return to Service)') {
        pmCompleted++;
      } else {
        pmPending++;
      }
    } else {
      cmTotal++;
      if (status === 'กำลังซ่อม') {
        cmInProgress++;
      } else if (status === 'รอตรวจสอบ' || status === 'รอ Supervisor ตรวจสอบ' || status === 'รอ Manager อนุมัติ' || status === 'รอผู้รับอุปกรณ์ลงนาม') {
        cmWaitingReview++;
      } else if (status === 'เสร็จสิ้น' || status === 'เสร็จสิ้น (Return to Service)') {
        cmCompleted++;
      } else {
        cmPending++;
      }
    }
  });

  updateCountsDisplay({ total: cmTotal, pending: cmPending, inProgress: cmInProgress, waitingReview: cmWaitingReview, completed: cmCompleted });
  updatePmCountsDisplay({ total: pmTotal, pending: pmPending, inProgress: pmProgress, waitingReview: pmWaitingReview, completed: pmCompleted });
  saveDashboardToLocalCache({ requests: allRequests });
}

function updateCountsDisplay(counts) {
  const totalEl = document.getElementById('totalCount');
  const pendEl = document.getElementById('pendingCount');
  const progEl = document.getElementById('progressCount');
  const revEl = document.getElementById('reviewCount');
  const compEl = document.getElementById('completedCount');

  if (totalEl) totalEl.textContent = counts.total || 0;
  if (pendEl) pendEl.textContent = counts.pending || 0;
  if (progEl) progEl.textContent = counts.inProgress || 0;
  if (revEl) revEl.textContent = counts.waitingReview || 0;
  if (compEl) compEl.textContent = counts.completed || 0;
}

function updatePmCountsDisplay(counts) {
  const totalEl = document.getElementById('pmTotalCount');
  const pendEl = document.getElementById('pmPendingCount');
  const progEl = document.getElementById('pmProgressCount');
  const revEl = document.getElementById('pmReviewCount');
  const compEl = document.getElementById('pmCompletedCount');

  if (totalEl) totalEl.textContent = counts.total || 0;
  if (pendEl) pendEl.textContent = counts.pending || 0;
  if (progEl) progEl.textContent = counts.inProgress || 0;
  if (revEl) revEl.textContent = counts.waitingReview || 0;
  if (compEl) compEl.textContent = counts.completed || 0;
}

function loadRequests() {
  loadDashboardData(false);
}

function loadStatusCounts() {
  recomputeAndUpdateCounts();
}

function renderTable(requests) {
  const tbody = document.getElementById('requestsTableBody');
  if (!tbody) return;

  // กรองเฉพาะใบแจ้งซ่อม CM เท่านั้น (ไม่แสดงรายการ PM ในหน้านี้เด็ดขาด)
  const cmRequests = (requests || []).filter(function(r) {
    return !isPmRequest(r);
  });

  if (!cmRequests || cmRequests.length === 0) {
    tbody.innerHTML = '<tr class="tr-empty"><td colspan="9" class="empty-message">' +
      '<i class="fas fa-inbox"></i><p>ไม่มีข้อมูลใบแจ้งซ่อม</p></td></tr>';
    return;
  }

  let html = '';
  cmRequests.forEach(function(r) {
    const userRole = (currentUser ? (currentUser.role || 'user') : 'user').toLowerCase();
    const userEmpId = (currentUser ? (currentUser.employeeId || '') : '').toUpperCase();
    const reqEmpId = (r.RequesterID || '').toString().trim().toUpperCase();
    const isOwner = reqEmpId === userEmpId;
    const isAdmin = userRole === 'admin';
    const isTech = userRole === 'technician';
    const isSup = userRole === 'supervisor';
    const isMgr = userRole === 'manager';
    const reqStatus = (r.Status || 'รอดำเนินการ').toString().trim();
    const statusClass = getStatusClass(reqStatus);

    const canEdit = isOwner || isAdmin;
    const canRepair = (isAdmin || isTech) && (reqStatus === 'กำลังซ่อม' || reqStatus === 'รอตรวจสอบ' || reqStatus === 'รอ Supervisor ตรวจสอบ');
    const canSupervisorApprove = (isAdmin || isSup) && reqStatus === 'รอ Supervisor ตรวจสอบ';
    const canManagerApprove = (isAdmin || isMgr) && reqStatus === 'รอ Manager อนุมัติ';
    const canAcceptEquipment = reqStatus === 'รอผู้รับอุปกรณ์ลงนาม';
    const canViewEndorsement = reqStatus === 'รอ Supervisor ตรวจสอบ' || reqStatus === 'รอ Manager อนุมัติ' || reqStatus === 'รอผู้รับอุปกรณ์ลงนาม' || reqStatus === 'เสร็จสิ้น' || reqStatus === 'เสร็จสิ้น (Return to Service)' || (r.MaintenanceDetails);
    const canResetWorkOrder = (isAdmin || isTech) && (reqStatus === 'รอ Supervisor ตรวจสอบ');

    html += '<tr class="request-card-row">';

    // 1. Request ID (On mobile: shows #ID + W/O badge)
    html += '<td class="col-req-id">' +
            '<div class="m-only m-card-req-header">' +
              '<span class="m-card-req-badge">#' + escapeHtml(r.RequestID || '-') + '</span>' +
              (r.WorkOrderNo ? '<span class="badge-wo m-card-wo"><i class="fas fa-file-invoice"></i> W/O ' + escapeHtml(r.WorkOrderNo) + '</span>' : '') +
            '</div>' +
            '<span class="dt-only"><strong>' + escapeHtml(r.RequestID || '-') + '</strong></span>' +
            '</td>';

    // 2. W/O (Desktop only column)
    html += '<td class="col-wo">' + (r.WorkOrderNo ? '<span class="badge-wo">' + escapeHtml(r.WorkOrderNo) + '</span>' : '-') + '</td>';

    // 3. Inform Date
    html += '<td class="col-date">' +
            '<span class="m-only m-cell-label"><i class="far fa-calendar-alt"></i> วันที่แจ้ง:</span>' +
            '<span class="m-cell-val">' + escapeHtml(r.InformDate || '-') + '</span>' +
            '</td>';

    // 4. Equipment Name (On mobile: shows Name + Code badge)
    html += '<td class="col-eq-name">' +
            '<div class="m-only m-cell-label"><i class="fas fa-truck-pickup"></i> อุปกรณ์ (GSE):</div>' +
            '<div class="m-only m-eq-val">' +
              '<strong class="m-eq-title">' + escapeHtml(r.EquipmentName || '-') + '</strong>' +
              (r.EquipmentCode ? '<span class="m-eq-code-badge">' + escapeHtml(r.EquipmentCode) + '</span>' : '') +
            '</div>' +
            '<span class="dt-only">' + escapeHtml(r.EquipmentName || '-') + '</span>' +
            '</td>';

    // 5. Equipment Code (Desktop only column)
    html += '<td class="col-eq-code cell-equipment-code">' + escapeHtml(r.EquipmentCode || '-') + '</td>';

    // 6. Damage Appearance
    html += '<td class="col-damage">' +
            '<div class="m-only m-cell-label"><i class="fas fa-tools"></i> อาการเสีย:</div>' +
            '<div class="damage-preview" title="' + escapeAttr(r.DamageAppearance || '') + '">' + escapeHtml(r.DamageAppearance || '-') + '</div>' +
            '</td>';

    // 7. Requester
    html += '<td class="col-requester">' +
            '<span class="m-only m-cell-label"><i class="far fa-user"></i> ผู้แจ้ง:</span>' +
            '<span class="m-cell-val">' + escapeHtml(r.RequesterName || '-') + '</span>' +
            '</td>';

    // 8. Status Badge
    html += '<td class="col-status">' +
            '<span class="status-badge ' + statusClass + '">' +
            escapeHtml(reqStatus) + '</span></td>';

    // 9. Actions
    html += '<td class="col-actions"><div class="actions-cell">';
    html += '<button class="btn btn-icon btn-print" title="พิมพ์" onclick=\'showPrintView("' + r.UUID + '")\'>' +
            '<i class="fas fa-print"></i><span class="btn-text">พิมพ์</span></button>';

    if (canSupervisorApprove) {
      html += '<button class="btn btn-icon btn-supervisor" title="ตรวจสอบงานซ่อม (Supervisor)" onclick=\'showEndorsementModal("' + r.UUID + '")\'>' +
              '<i class="fas fa-clipboard-check"></i><span class="btn-text">ตรวจสอบ</span></button>';
    }

    if (canManagerApprove) {
      html += '<button class="btn btn-icon btn-manager" title="อนุมัติงานซ่อม (Manager)" onclick=\'showEndorsementModal("' + r.UUID + '")\'>' +
              '<i class="fas fa-stamp"></i><span class="btn-text">อนุมัติ</span></button>';
    }

    if (canAcceptEquipment) {
      html += '<button class="btn btn-icon btn-acceptance" title="ลงนามรับมอบอุปกรณ์ (Return to Service)" onclick=\'showEndorsementModal("' + r.UUID + '")\'>' +
              '<i class="fas fa-handshake"></i><span class="btn-text">รับมอบรถ</span></button>';
    }

    if (!canSupervisorApprove && !canManagerApprove && !canAcceptEquipment && canViewEndorsement) {
      html += '<button class="btn btn-icon btn-endorse-info" title="ดูรายละเอียดผลการซ่อมและสถานะอนุมัติ" onclick=\'showEndorsementModal("' + r.UUID + '")\'>' +
              '<i class="fas fa-info-circle"></i><span class="btn-text">ผลการซ่อม</span></button>';
    }

    if (canRepair) {
      html += '<button class="btn btn-icon btn-repair" title="บันทึกผลการซ่อมบำรุง" onclick=\'showTechnicianForm("' + r.UUID + '")\'>' +
              '<i class="fas fa-wrench"></i><span class="btn-text">บันทึกผลซ่อม</span></button>';
    }

    if (canResetWorkOrder) {
      html += '<button class="btn btn-icon btn-reset-tech" title="รีเซ็ต / ดึงกลับใบงาน (ช่าง/Admin)" onclick=\'openResetModal("' + r.UUID + '", "' + escapeAttr(r.EquipmentCode || '') + '", "' + escapeAttr(r.WorkOrderNo || '') + '")\'>' +
              '<i class="fas fa-undo-alt"></i><span class="btn-text">ดึงกลับ</span></button>';
    }

    if (canEdit) {
      html += '<button class="btn btn-icon btn-edit" title="แก้ไข" onclick=\'showEditForm("' + r.UUID + '")\'>' +
              '<i class="fas fa-edit"></i><span class="btn-text">แก้ไข</span></button>';
    }

    // ปุ่มสำหรับ Admin ปิด W/O ใน Sheet (เปิดให้กดทันทีที่ Supervisor ตรวจสอบแล้ว คือ รอ Manager อนุมัติ เป็นต้นไป)
    if (isAdmin && (reqStatus === 'รอ Manager อนุมัติ' || reqStatus === 'รอผู้รับอุปกรณ์ลงนาม' || reqStatus === 'เสร็จสิ้น' || reqStatus === 'เสร็จสิ้น (Return to Service)')) {
      if (r.WoSheetStatus === 'CLOSED') {
        html += '<button class="btn btn-icon btn-wo-closed" title="W/O ใน Sheet ปิดแล้ว (CLOSED)" disabled><i class="fas fa-check-circle"></i><span class="btn-text">W/O ปิดแล้ว</span></button>';
      } else {
        html += '<button class="btn btn-icon btn-close-wo" title="Admin: ปิด W/O ใน Sheet ทันที" onclick=\'handleDirectCloseWo("' + r.UUID + '")\'><i class="fas fa-folder-minus"></i><span class="btn-text">ปิด W/O</span></button>';
      }
    }

    if (isAdmin) {
      html += '<button class="btn btn-icon btn-delete" title="ลบ" onclick=\'showDeleteModal("' + r.UUID + '", "' +
              escapeHtml(r.RequestID || '') + '")\'><i class="fas fa-trash"></i><span class="btn-text">ลบ</span></button>';
    }
    html += '</div></td>';
    html += '</tr>';
  });

  tbody.innerHTML = html;
}

function getStatusClass(status) {
  switch (status) {
    case 'กำลังซ่อม': return 'status-progress';
    case 'รอตรวจสอบ':
    case 'รอ Supervisor ตรวจสอบ': return 'status-supervisor';
    case 'รอ Manager อนุมัติ': return 'status-manager';
    case 'รอผู้รับอุปกรณ์ลงนาม': return 'status-acceptance';
    case 'เสร็จสิ้น':
    case 'เสร็จสิ้น (Return to Service)': return 'status-completed';
    default: return 'status-pending';
  }
}

function filterTable() {
  const searchTerm = document.getElementById('searchInput').value.toLowerCase().trim();
  const statusFilter = document.getElementById('statusFilter').value;

  let filtered = (allRequests || []).filter(function(r) {
    return !isPmRequest(r);
  });

  if (statusFilter) {
    filtered = filtered.filter(function(r) {
      return (r.Status || 'รอดำเนินการ') === statusFilter;
    });
  }

  if (searchTerm) {
    filtered = filtered.filter(function(r) {
      return (r.RequestID || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.WorkOrderNo || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.EquipmentName || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.EquipmentCode || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.RequesterName || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.DamageAppearance || '').toString().toLowerCase().indexOf(searchTerm) !== -1;
    });
  }

  renderTable(filtered);
}

// === GSE STATUS & PM DASHBOARD TAB LOGIC ===
let currentGseStatusFilter = '';
let currentGseSearchTerm = '';

function switchDashboardTab(tab) {
  currentDashboardTab = tab;
  const tabReq = document.getElementById('tabNavRequests');
  const tabPm = document.getElementById('tabNavPm');
  const tabGse = document.getElementById('tabNavGseStatus');
  const viewReq = document.getElementById('viewRequests');
  const viewPm = document.getElementById('viewPm');
  const viewGse = document.getElementById('viewGseStatus');

  if (tabReq) tabReq.classList.remove('active');
  if (tabPm) tabPm.classList.remove('active');
  if (tabGse) tabGse.classList.remove('active');
  if (viewReq) viewReq.style.display = 'none';
  if (viewPm) viewPm.style.display = 'none';
  if (viewGse) viewGse.style.display = 'none';

  if (tab === 'gse_status') {
    if (tabGse) tabGse.classList.add('active');
    if (viewGse) viewGse.style.display = 'block';
    renderGseDashboard();
  } else if (tab === 'pm') {
    const isAdmin = currentUser && (currentUser.role === 'admin');
    if (!isAdmin) {
      if (tabReq) tabReq.classList.add('active');
      if (viewReq) viewReq.style.display = 'block';
      showToast('เมนูแผน PM เปิดให้เฉพาะ Admin เข้าใช้งานในขณะนี้', 'warning');
      filterTable();
      return;
    }
    if (tabPm) tabPm.classList.add('active');
    if (viewPm) viewPm.style.display = 'block';
    renderPmDashboard();
  } else {
    if (tabReq) tabReq.classList.add('active');
    if (viewReq) viewReq.style.display = 'block';
    filterTable();
  }
}

let gseAvailabilityChartInstance = null;
let gseBreakdownChartInstance = null;
let currentGseTypeFilter = '';

/**
 * ตารางจับคู่รหัสประเภทและชื่อเต็มมาตรฐาน ดึงตรงตามฐานข้อมูล Sheet GSE DMK
 */
const GSE_PREFIX_NAME_MAP = {
  'AC': 'AIR CONDITIONING UNIT',
  'AS': 'AIR STARTER UNIT',
  'BC': 'BAGGAGE CART',
  'BU': 'PASSENGER BUS',
  'CB': 'CONVEYOR BELT',
  'ES': 'ENGINEERING STEP',
  'EX': 'EXTINGUISHER',
  'FL': 'FORKLIFT',
  'GE': 'GENERATOR',
  'GP': 'GROUND POWER UNIT',
  'GPU': 'GROUND POWER UNIT',
  'HT': 'HAND LIFT',
  'LV': 'LAVATORY TRUCK',
  'MP': 'MAINTENANCE PLATFORM',
  'N2': 'WHEEL AND NITROGEN CART',
  'PB': 'AIRCRAFT TOWING TRACTOR',
  'PS': 'PASSENGER STEP',
  'PU': 'PICK UP',
  'PW': 'POTABLE WATER TRUCK',
  'TB': 'AIRCRAFT TOWBAR',
  'TR': 'BAGGAGE TOWING TRACTOR',
  'TT': 'TRANSPORT TRUCK',
  'VA': 'VAN',
  'VP': 'SMALL VAN (VIP)',
  'WA': 'WATER PUMP COMPRESSOR WASH',
  'WT': 'WATER TRUCK'
};

/**
 * getGseEquipmentType - แปลงรหัสหรือชื่ออุปกรณ์เป็นประเภทรถมาตรฐาน DMK GSE
 * โดยดึงจากข้อมูลใน Google Sheet ทะเบียนอุปกรณ์ GSE เป็นหลัก
 */
function getGseEquipmentType(code, name) {
  const normCode = (code || '').toUpperCase().trim();
  const normName = (name || '').toUpperCase().trim();

  // ดึง prefix เช่น TLM-BU-009 -> BU, TLM-MP-001 -> MP, TLM-TR-005 -> TR
  const match = normCode.match(/^TLM-([A-Z0-9]+)-/);
  const prefix = match ? match[1] : '';

  // 1. ดึงชื่อ Description จาก equipmentMasterList สดจาก Sheet ก่อนเสมอ
  let descFromMaster = '';
  if (equipmentMasterList && equipmentMasterList.length > 0 && normCode) {
    const item = equipmentMasterList.find(function(x) {
      return (x.gseNo || '').toUpperCase().trim() === normCode;
    });
    if (item && item.description) {
      descFromMaster = item.description.trim().toUpperCase();
      // ลบคำต่อท้าย เช่น / ROOFLESS หรือ / SINGLE CAB เพื่อให้ชื่อกระชับสวยงาม
      descFromMaster = descFromMaster.replace(/\s*\/.*$/, '').trim();
    }
  }

  // 2. หาชื่อเต็มจากตาราง Map หรือจาก Description ที่ได้จากชีต
  let fullTitle = '';
  if (prefix && GSE_PREFIX_NAME_MAP[prefix]) {
    fullTitle = GSE_PREFIX_NAME_MAP[prefix];
  } else if (descFromMaster) {
    fullTitle = descFromMaster;
  }

  // ถ้าได้ชื่อเต็มและมีตัวย่อ ให้แสดง: "ชื่อเต็ม (ตัวย่อ)" เช่น "PASSENGER BUS (BU)", "MAINTENANCE PLATFORM (MP)"
  if (fullTitle && prefix) {
    return fullTitle + ' (' + prefix + ')';
  } else if (fullTitle) {
    return fullTitle;
  }

  // 3. ตรวจสอบชื่ออุปกรณ์ที่ส่งมา (name)
  if (normName) {
    const cleanName = normName.split('(')[0].trim();
    if (cleanName && prefix) {
      return cleanName + ' (' + prefix + ')';
    }
    if (cleanName) {
      return cleanName;
    }
  }

  // 4. Fallback สุดท้ายถ้าไม่มีข้อมูลเลย
  if (prefix) return prefix;
  return 'OTHER GSE';
}

/**
 * renderGseCharts - วาด/อัปเดตกราฟ GSE Fleet Availability และ Breakdown by Vehicle Type
 */
function renderGseCharts() {
  if (typeof Chart === 'undefined') {
    setTimeout(renderGseCharts, 250);
    return;
  }

  if (equipmentMasterList === null) {
    loadEquipmentMaster(function() {
      renderGseCharts();
    });
  }

  // 1. คัดกรองรายการรถที่เสีย/กำลังซ่อมอยู่จริง (Active Defective Requests)
  const activeDefectiveRequests = (allRequests || []).filter(function(r) {
    const st = (r.Status || 'รอดำเนินการ').toString().trim();
    return st !== 'เสร็จสิ้น' && st !== 'เสร็จสิ้น (Return to Service)';
  });

  const uniqueBrokenCodes = new Set();
  const typeCounts = {};

  activeDefectiveRequests.forEach(function(r) {
    const code = (r.EquipmentCode || '').toString().trim().toUpperCase();
    const name = (r.EquipmentName || '').toString().trim();
    if (code) uniqueBrokenCodes.add(code);

    const typeName = getGseEquipmentType(code, name);
    typeCounts[typeName] = (typeCounts[typeName] || 0) + 1;
  });

  // 2. คำนวณยอดฝูงรถทั้งหมด (Total Fleet)
  let totalFleet = 0;
  if (equipmentMasterList && equipmentMasterList.length > 0) {
    totalFleet = equipmentMasterList.length;
  } else {
    totalFleet = Math.max(uniqueBrokenCodes.size + 150, 186);
  }

  const unserviceableCount = uniqueBrokenCodes.size || activeDefectiveRequests.length;
  const serviceableCount = Math.max(0, totalFleet - unserviceableCount);

  const serviceablePct = totalFleet > 0 ? ((serviceableCount / totalFleet) * 100).toFixed(1) : '0.0';
  const unserviceablePct = totalFleet > 0 ? ((unserviceableCount / totalFleet) * 100).toFixed(1) : '0.0';

  // อัปเดตข้อมูลบน UI Card
  const pillEl = document.getElementById('gseAvailabilityRateText');
  if (pillEl) pillEl.textContent = serviceablePct + '%';
  const centerPctEl = document.getElementById('gseCenterPercent');
  if (centerPctEl) centerPctEl.textContent = serviceablePct + '%';

  const valServEl = document.getElementById('valServiceableCount');
  if (valServEl) valServEl.textContent = serviceableCount;
  const valServPctEl = document.getElementById('valServiceablePct');
  if (valServPctEl) valServPctEl.textContent = serviceablePct + '%';

  const valUnservEl = document.getElementById('valUnserviceableCount');
  if (valUnservEl) valUnservEl.textContent = unserviceableCount;
  const valUnservPctEl = document.getElementById('valUnserviceablePct');
  if (valUnservPctEl) valUnservPctEl.textContent = unserviceablePct + '%';

  const valTotalEl = document.getElementById('valTotalFleetCount');
  if (valTotalEl) valTotalEl.textContent = totalFleet + ' คัน';

  const brokenPillEl = document.getElementById('gseTotalBrokenTypesCount');
  if (brokenPillEl) brokenPillEl.textContent = unserviceableCount;

  // 3. Render / Update Donut Chart (GSE Fleet Availability)
  if (typeof Chart === 'undefined') {
    setTimeout(renderGseDashboard, 200);
    return;
  }

  const availCanvas = document.getElementById('gseAvailabilityChart');
  if (availCanvas) {
    if (gseAvailabilityChartInstance) {
      gseAvailabilityChartInstance.data.datasets[0].data = [serviceableCount, unserviceableCount];
      gseAvailabilityChartInstance.update();
    } else {
      gseAvailabilityChartInstance = new Chart(availCanvas, {
        type: 'doughnut',
        data: {
          labels: ['Serviceable (พร้อมใช้งาน)', 'Unserviceable (ไม่พร้อมใช้งาน/เสีย)'],
          datasets: [{
            data: [serviceableCount, unserviceableCount],
            backgroundColor: ['#10B981', '#EF4444'],
            hoverBackgroundColor: ['#059669', '#DC2626'],
            borderColor: '#FFFFFF',
            borderWidth: 3,
            hoverOffset: 6
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          cutout: '72%',
          plugins: {
            legend: { display: false },
            tooltip: {
              backgroundColor: '#1E293B',
              titleFont: { family: 'Sarabun', size: 13, weight: 'bold' },
              bodyFont: { family: 'Sarabun', size: 12 },
              padding: 10,
              cornerRadius: 8,
              callbacks: {
                label: function(context) {
                  const val = context.raw || 0;
                  const pct = totalFleet > 0 ? ((val / totalFleet) * 100).toFixed(1) : 0;
                  return ' ' + context.label + ': ' + val + ' คัน (' + pct + '%)';
                }
              }
            }
          }
        }
      });
    }
  }

  // 4. Render / Update Horizontal Bar Chart (Breakdown by Type)
  const breakdownCanvas = document.getElementById('gseBreakdownChart');
  const emptyMsgEl = document.getElementById('noBrokenVehiclesMessage');

  const sortedTypes = Object.keys(typeCounts).sort(function(a, b) {
    return typeCounts[b] - typeCounts[a];
  });

  if (sortedTypes.length === 0) {
    if (breakdownCanvas) breakdownCanvas.style.display = 'none';
    if (emptyMsgEl) emptyMsgEl.style.display = 'flex';
    if (gseBreakdownChartInstance) {
      gseBreakdownChartInstance.destroy();
      gseBreakdownChartInstance = null;
    }
  } else {
    if (breakdownCanvas) breakdownCanvas.style.display = 'block';
    if (emptyMsgEl) emptyMsgEl.style.display = 'none';

    const barLabels = sortedTypes;
    const barData = sortedTypes.map(function(t) { return typeCounts[t]; });

    const barColors = [
      '#EF4444', '#F97316', '#F59E0B', '#E11D48',
      '#8B5CF6', '#3B82F6', '#64748B', '#06B6D4'
    ];

    if (gseBreakdownChartInstance) {
      gseBreakdownChartInstance.data.labels = barLabels;
      gseBreakdownChartInstance.data.datasets[0].data = barData;
      gseBreakdownChartInstance.data.datasets[0].backgroundColor = barColors.slice(0, barLabels.length);
      gseBreakdownChartInstance.update();
    } else {
      gseBreakdownChartInstance = new Chart(breakdownCanvas, {
        type: 'bar',
        data: {
          labels: barLabels,
          datasets: [{
            label: 'จำนวนรถที่เสีย (คัน)',
            data: barData,
            backgroundColor: barColors.slice(0, barLabels.length),
            borderRadius: 6,
            borderSkipped: false,
            barThickness: 18,
            maxBarThickness: 24
          }]
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: {
              backgroundColor: '#1E293B',
              titleFont: { family: 'Sarabun', size: 13, weight: 'bold' },
              bodyFont: { family: 'Sarabun', size: 12 },
              padding: 10,
              cornerRadius: 8,
              callbacks: {
                label: function(context) {
                  const val = context.raw || 0;
                  const pct = unserviceableCount > 0 ? ((val / unserviceableCount) * 100).toFixed(1) : 0;
                  return ' กำลังซ่อม/รอดำเนินการ: ' + val + ' คัน (' + pct + '% ของรถที่เสีย)';
                }
              }
            }
          },
          scales: {
            x: {
              beginAtZero: true,
              ticks: {
                stepSize: 1,
                precision: 0,
                font: { family: 'Sarabun', size: 11 }
              },
              grid: { color: '#F1F5F9' }
            },
            y: {
              ticks: {
                font: { family: 'Sarabun', size: 11.5, weight: '600' },
                color: '#334155'
              },
              grid: { display: false }
            }
          },
          onClick: function(evt, elements) {
            if (!elements || elements.length === 0) return;
            const idx = elements[0].index;
            const selectedType = barLabels[idx];
            handleFilterGseByType(selectedType);
          },
          onHover: function(evt, activeElements) {
            evt.native.target.style.cursor = (activeElements && activeElements.length > 0) ? 'pointer' : 'default';
          }
        }
      });
    }
  }
}

/**
 * กรองตารางเมื่อผู้ใช้คลิกเลือกประเภทรถในกราฟ Bar Chart
 */
function handleFilterGseByType(typeName) {
  currentGseTypeFilter = typeName;

  const notice = document.getElementById('gseFilterNotice');
  const noticeText = document.getElementById('gseFilterNoticeText');
  if (notice && noticeText) {
    noticeText.textContent = 'ประเภท ' + typeName;
    notice.style.display = 'inline-flex';
  }

  renderGseDashboard();

  const activeBlock = document.getElementById('gseActiveBlock');
  if (activeBlock) {
    activeBlock.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

function filterGseStatus(status) {
  currentGseStatusFilter = status;
  const notice = document.getElementById('gseFilterNotice');
  const noticeText = document.getElementById('gseFilterNoticeText');
  if (!status) {
    currentGseTypeFilter = '';
    currentGseSearchTerm = '';
    const searchInput = document.getElementById('gseSearchInput');
    if (searchInput) searchInput.value = '';
    if (notice) notice.style.display = 'none';
  } else if (notice && noticeText) {
    noticeText.textContent = status;
    notice.style.display = 'inline-flex';
  }
  renderGseDashboard();
}

function handleGseSearch() {
  const input = document.getElementById('gseSearchInput');
  currentGseSearchTerm = input ? input.value.toLowerCase().trim() : '';
  renderGseDashboard();
}

function renderGseDashboard() {
  if (!allRequests) return;

  // 1. คำนวณยอดสรุปจำนวนอุปกรณ์ทั้งหมด
  let totalDefective = allRequests.length;
  let inProgress = 0;
  let pendingOrReview = 0;
  let completed = 0;

  allRequests.forEach(function(r) {
    const st = (r.Status || 'รอดำเนินการ').toString().trim();
    if (st === 'กำลังซ่อม') {
      inProgress++;
    } else if (st === 'เสร็จสิ้น' || st === 'เสร็จสิ้น (Return to Service)') {
      completed++;
    } else {
      pendingOrReview++; // รอดำเนินการ, รอตรวจสอบ, รอ Supervisor ตรวจสอบ, รอ Manager อนุมัติ, รอผู้รับอุปกรณ์ลงนาม
    }
  });

  const totalEl = document.getElementById('gseTotalCount');
  if (totalEl) totalEl.textContent = totalDefective;
  const progEl = document.getElementById('gseProgressCount');
  if (progEl) progEl.textContent = inProgress;
  const pendEl = document.getElementById('gsePendingCount');
  if (pendEl) pendEl.textContent = pendingOrReview;
  const compEl = document.getElementById('gseCompletedCount');
  if (compEl) compEl.textContent = completed;

  // 1.5 วาด/อัปเดตกราฟ GSE Fleet Availability & Breakdown by Vehicle Type
  renderGseCharts();

  // 2. กรองข้อมูลตามเงื่อนไข (status filter + type filter + search term)
  let filtered = allRequests.filter(function(r) {
    const st = (r.Status || 'รอดำเนินการ').toString().trim();
    const isCompleted = st === 'เสร็จสิ้น' || st === 'เสร็จสิ้น (Return to Service)';
    if (currentGseStatusFilter) {
      if (currentGseStatusFilter === 'กำลังซ่อม' && st !== 'กำลังซ่อม') return false;
      if (currentGseStatusFilter === 'เสร็จสิ้น' && !isCompleted) return false;
      if (currentGseStatusFilter === 'รอดำเนินการ' && (st === 'กำลังซ่อม' || isCompleted)) return false;
    }
    if (currentGseTypeFilter) {
      const eqType = getGseEquipmentType(r.EquipmentCode, r.EquipmentName);
      if (eqType !== currentGseTypeFilter) return false;
    }
    if (currentGseSearchTerm) {
      const q = currentGseSearchTerm;
      const tlm = (r.EquipmentCode || '').toLowerCase();
      const eqName = (r.EquipmentName || '').toLowerCase();
      const damage = (r.DamageAppearance || '').toLowerCase();
      const details = (r.MaintenanceDetails || '').toLowerCase();
      const typeLabel = getGseEquipmentType(r.EquipmentCode, r.EquipmentName).toLowerCase();
      if (!tlm.includes(q) && !eqName.includes(q) && !damage.includes(q) && !details.includes(q) && !wo.includes(q) && !typeLabel.includes(q)) {
        return false;
      }
    }
    return true;
  });

  // 3. แยกเป็นกลุ่มรายการที่กำลังซ่อม (Active) และรายการที่เสร็จสิ้นแล้ว (Completed)
  const activeList = filtered.filter(function(r) {
    const st = (r.Status || 'รอดำเนินการ').toString().trim();
    return st !== 'เสร็จสิ้น' && st !== 'เสร็จสิ้น (Return to Service)';
  });
  const completedList = filtered.filter(function(r) {
    const st = (r.Status || '').toString().trim();
    return st === 'เสร็จสิ้น' || st === 'เสร็จสิ้น (Return to Service)';
  });

  // อัปเดตตัวเลขบนหัว Banner
  const activeCountEl = document.getElementById('gseActiveTableCount');
  if (activeCountEl) activeCountEl.textContent = activeList.length + ' รายการ';
  const completedCountEl = document.getElementById('gseCompletedTableCount');
  if (completedCountEl) completedCountEl.textContent = completedList.length + ' รายการ';

  // ซ่อน/แสดงบล็อกตารางตามการกรอง
  const activeBlock = document.getElementById('gseActiveBlock');
  const completedBlock = document.getElementById('gseCompletedBlock');
  if (activeBlock) {
    activeBlock.style.display = (currentGseStatusFilter === 'เสร็จสิ้น') ? 'none' : 'block';
  }
  if (completedBlock) {
    completedBlock.style.display = (currentGseStatusFilter && currentGseStatusFilter !== 'เสร็จสิ้น') ? 'none' : 'block';
  }

  // 4. แสดงผลตาราง Active (DMK GSE MAINTENANCE STATUS)
  const activeTbody = document.getElementById('gseActiveTableBody');
  if (activeTbody) {
    if (activeList.length === 0) {
      activeTbody.innerHTML = '<tr><td colspan="9" class="empty-message"><i class="fas fa-check-circle" style="color:var(--success);opacity:0.7;"></i><p>ไม่มีอุปกรณ์ที่อยู่ระหว่างการซ่อม</p></td></tr>';
    } else {
      let html = '';
      activeList.forEach(function(r, index) {
        const st = (r.Status || 'รอดำเนินการ').toString().trim();
        const statusClass = getStatusClass(st);
        const userRole = (currentUser ? (currentUser.role || 'user') : 'user').toLowerCase();
        const userEmpId = (currentUser ? (currentUser.employeeId || '') : '').toUpperCase();
        const reqEmpId = (r.RequesterID || '').toString().trim().toUpperCase();
        const isOwner = reqEmpId === userEmpId;
        const isAdmin = userRole === 'admin';
        const isSup = userRole === 'supervisor';
        const isMgr = userRole === 'manager';

        const canSupervisorApprove = (isAdmin || isSup) && st === 'รอ Supervisor ตรวจสอบ';
        const canManagerApprove = (isAdmin || isMgr) && st === 'รอ Manager อนุมัติ';
        const canAcceptEquipment = st === 'รอผู้รับอุปกรณ์ลงนาม';
        const canViewEndorsement = st === 'รอ Supervisor ตรวจสอบ' || st === 'รอ Manager อนุมัติ' || st === 'รอผู้รับอุปกรณ์ลงนาม' || (r.MaintenanceDetails);

        let statusBadge = '<span class="status-badge ' + statusClass + '">' + escapeHtml(st) + '</span>';
        if (st === 'กำลังซ่อม') {
          statusBadge = '<span class="status-badge status-progress"><i class="fas fa-wrench"></i> Maintenance Process</span>';
        } else if (st === 'รอ Supervisor ตรวจสอบ') {
          statusBadge = '<span class="status-badge status-supervisor"><i class="fas fa-clipboard-check"></i> รอ Supervisor ตรวจสอบ</span>';
        } else if (st === 'รอ Manager อนุมัติ') {
          statusBadge = '<span class="status-badge status-manager"><i class="fas fa-stamp"></i> รอ Manager อนุมัติ</span>';
        } else if (st === 'รอผู้รับอุปกรณ์ลงนาม') {
          statusBadge = '<span class="status-badge status-acceptance"><i class="fas fa-handshake"></i> รอรับมอบอุปกรณ์</span>';
        }

        html += '<tr>';
        html += '<td style="text-align:center; font-weight:600; color:var(--gray);">' + (index + 1) + '</td>';
        html += '<td class="cell-equipment-code"><strong>' + escapeHtml(r.EquipmentCode || '-') + '</strong></td>';
        html += '<td>' + escapeHtml(r.EquipmentName || '-') + '</td>';
        html += '<td>' + escapeHtml(r.InformDate || '-') + '</td>';
        html += '<td><div class="gse-table-details" title="' + escapeAttr(r.DamageAppearance || '') + '">' + escapeHtml(r.DamageAppearance || '-') + '</div></td>';
        html += '<td>' + (r.EstimateDate ? '<span class="badge-rts">' + escapeHtml(r.EstimateDate) + '</span>' : '<span style="color:var(--gray);">-</span>') + '</td>';
        html += '<td>' + (r.WorkOrderNo ? '<span class="badge-wo">' + escapeHtml(r.WorkOrderNo) + '</span>' : '-') + '</td>';
        html += '<td>' + statusBadge + '</td>';
        html += '<td><div class="actions-cell">';
        html += '<button class="btn btn-icon btn-print" title="ดู/พิมพ์ใบแจ้งซ่อม" onclick=\'showPrintView("' + r.UUID + '")\'><i class="fas fa-print"></i></button>';
        if (canSupervisorApprove) {
          html += '<button class="btn btn-icon btn-supervisor" title="ตรวจสอบงานซ่อม (Supervisor)" onclick=\'showEndorsementModal("' + r.UUID + '")\'><i class="fas fa-clipboard-check"></i></button>';
        } else if (canManagerApprove) {
          html += '<button class="btn btn-icon btn-manager" title="อนุมัติงานซ่อม (Manager)" onclick=\'showEndorsementModal("' + r.UUID + '")\'><i class="fas fa-stamp"></i></button>';
        } else if (canAcceptEquipment) {
          html += '<button class="btn btn-icon btn-acceptance" title="ลงนามรับมอบอุปกรณ์ (Return to Service)" onclick=\'showEndorsementModal("' + r.UUID + '")\'><i class="fas fa-handshake"></i></button>';
        } else if (canViewEndorsement) {
          html += '<button class="btn btn-icon btn-endorse-info" title="ดูรายละเอียดงานซ่อมและสถานะอนุมัติ" onclick=\'showEndorsementModal("' + r.UUID + '")\'><i class="fas fa-info-circle"></i></button>';
        }
        if (isAdmin && (st === 'รอ Manager อนุมัติ' || st === 'รอผู้รับอุปกรณ์ลงนาม')) {
          if (r.WoSheetStatus === 'CLOSED') {
            html += '<button class="btn btn-icon btn-wo-closed" title="W/O ใน Sheet ปิดแล้ว (CLOSED)" disabled><i class="fas fa-check-circle"></i></button>';
          } else {
            html += '<button class="btn btn-icon btn-close-wo" title="Admin: ปิด W/O ใน Sheet ทันที" onclick=\'handleDirectCloseWo("' + r.UUID + '")\'><i class="fas fa-folder-minus"></i></button>';
          }
        }
        html += '</div></td>';
        html += '</tr>';
      });
      activeTbody.innerHTML = html;
    }
  }

  // 5. แสดงผลตาราง Completed Tasks
  const completedTbody = document.getElementById('gseCompletedTableBody');
  if (completedTbody) {
    if (completedList.length === 0) {
      completedTbody.innerHTML = '<tr><td colspan="9" class="empty-message"><i class="fas fa-clipboard-list"></i><p>ไม่มีรายการที่เสร็จสิ้น</p></td></tr>';
    } else {
      let html = '';
      completedList.forEach(function(r, index) {
        const details = r.MaintenanceDetails || r.DamageAppearance || '-';
        const rtsDate = r.CompleteDate || r.EstimateDate || r.InformDate || '-';
        const isAdmin = currentUser.role === 'admin';

        html += '<tr>';
        html += '<td style="text-align:center; font-weight:600; color:var(--gray);">' + (index + 1) + '</td>';
        html += '<td class="cell-equipment-code"><strong>' + escapeHtml(r.EquipmentCode || '-') + '</strong></td>';
        html += '<td>' + escapeHtml(r.EquipmentName || '-') + '</td>';
        html += '<td>' + escapeHtml(r.InformDate || '-') + '</td>';
        html += '<td><div class="gse-table-details" title="' + escapeAttr(details) + '">' + escapeHtml(details) + '</div></td>';
        html += '<td><span class="badge-completed-date">' + escapeHtml(rtsDate) + '</span></td>';
        html += '<td>' + (r.WorkOrderNo ? '<span class="badge-wo">' + escapeHtml(r.WorkOrderNo) + '</span>' : '-') + '</td>';
        html += '<td><span class="status-badge status-completed"><i class="fas fa-check"></i> Return to Service</span></td>';
        html += '<td><div class="actions-cell">';
        html += '<button class="btn btn-icon btn-print" title="ดู/พิมพ์ใบแจ้งซ่อม" onclick=\'showPrintView("' + r.UUID + '")\'><i class="fas fa-print"></i></button>';
        html += '<button class="btn btn-icon btn-endorse-info" title="ดูรายละเอียดผลการซ่อมและการลงนาม" onclick=\'showEndorsementModal("' + r.UUID + '")\'><i class="fas fa-info-circle"></i></button>';
        if (isAdmin) {
          if (r.WoSheetStatus === 'CLOSED') {
            html += '<button class="btn btn-icon btn-wo-closed" title="W/O ใน Sheet ปิดแล้ว (CLOSED)" disabled><i class="fas fa-check-circle"></i></button>';
          } else {
            html += '<button class="btn btn-icon btn-close-wo" title="Admin: ปิด W/O ใน Sheet ทันที" onclick=\'handleDirectCloseWo("' + r.UUID + '")\'><i class="fas fa-folder-minus"></i></button>';
          }
        }
        html += '</div></td>';
        html += '</tr>';
      });
      completedTbody.innerHTML = html;
    }
  }
}

// === CREATE / EDIT FORM ===
function showCreateForm() {
  document.getElementById('formTitle').textContent = 'สร้างใบแจ้งซ่อมใหม่';
  document.getElementById('formMode').value = 'create';
  document.getElementById('formUUID').value = '';

  // เคลียร์ฟอร์ม
  document.getElementById('requestForm').reset();
  document.getElementById('equipmentDropdown').style.display = 'none';
  const warnEl = document.getElementById('equipmentInactiveWarning');
  if (warnEl) warnEl.style.display = 'none';

  // Auto-fill ข้อมูลผู้แจ้ง
  document.getElementById('fRequesterName').value = currentUser.fullName;
  document.getElementById('fRequesterId').value = currentUser.employeeId;

  // ตั้งวันที่ปัจจุบัน
  const today = new Date();
  document.getElementById('fInformDate').value = formatDateForInput(today);
  document.getElementById('fInformTime').value = formatTimeForInput(today);

  // แสดง/ซ่อนส่วนที่ 2 ตาม role
  document.getElementById('section2').style.display =
    currentUser.role === 'admin' ? 'block' : 'none';

  // เปิดให้แก้ไขฟิลด์ส่วนที่ 1
  setFormFieldsEditable(true);

  // ล้างสถานะกรอบสีแดงของรหัสอุปกรณ์
  const eqInput = document.getElementById('fEquipmentCode');
  if (eqInput) {
    eqInput.style.borderColor = '';
    eqInput.style.boxShadow = '';
  }

  // โหลดรายการอุปกรณ์ล่วงหน้า (background) เพื่อให้ dropdown รวดเร็ว
  loadEquipmentMaster();

  showPage('formPage');
}


function showEditForm(uuid) {
  showLoading();

  google.script.run
    .withSuccessHandler(function(request) {
      hideLoading();
      if (!request) {
        showToast('ไม่พบข้อมูลใบแจ้งซ่อม', 'error');
        return;
      }

      // ล้างการแจ้งเตือนรหัสอุปกรณ์ตกค้าง และโหลด Master
      const editWarnEl = document.getElementById('equipmentInactiveWarning');
      if (editWarnEl) editWarnEl.style.display = 'none';
      const editEqInput = document.getElementById('fEquipmentCode');
      if (editEqInput) {
        editEqInput.style.borderColor = '';
        editEqInput.style.boxShadow = '';
      }
      loadEquipmentMaster();

      document.getElementById('formTitle').textContent = 'แก้ไขใบแจ้งซ่อม: ' + (request.RequestID || '');
      document.getElementById('formMode').value = 'edit';
      document.getElementById('formUUID').value = uuid;

      // เติมข้อมูลส่วนที่ 1
      document.getElementById('fInformDate').value = parseDateToInput(request.InformDate);
      document.getElementById('fInformTime').value = parseTimeToInput(request.InformTime);
      document.getElementById('fEquipmentName').value = request.EquipmentName || '';
      document.getElementById('fEquipmentCode').value = request.EquipmentCode || '';
      document.getElementById('fHrKm').value = request.HrKm || '';
      document.getElementById('fDueDate').value = parseDateToInput(request.DueDate);
      document.getElementById('fDamageAppearance').value = request.DamageAppearance || '';
      document.getElementById('fRequesterName').value = request.RequesterName || '';
      document.getElementById('fRequesterId').value = request.RequesterID || '';
      document.getElementById('fApproverName').value = request.ApproverName || '';
      document.getElementById('fApproverTel').value = request.ApproverTel || '';

      // ตรวจสอบสิทธิ์แก้ไข
      const userEmpId = (currentUser.employeeId || '').toUpperCase();
      const reqEmpId = (request.RequesterID || '').toString().trim().toUpperCase();
      const isOwner = reqEmpId === userEmpId;
      const isAdmin = currentUser.role === 'admin';

      // ถ้าเป็น user ที่ไม่ใช่เจ้าของ → ไม่ให้แก้ไข
      if (!isOwner && !isAdmin) {
        showToast('คุณไม่มีสิทธิ์แก้ไขใบแจ้งซ่อมของผู้อื่น (สามารถดูและพิมพ์ได้เท่านั้น)', 'error');
        return;
      }

      // เปิดให้แก้ไขฟิลด์ส่วนที่ 1
      setFormFieldsEditable(true);

      // แสดง/ซ่อนส่วนที่ 2
      if (isAdmin) {
        document.getElementById('section2').style.display = 'block';
        document.getElementById('fRequestId').value = request.RequestID || '';
        document.getElementById('fReceivedDate').value = parseDateToInput(request.ReceivedDate) || formatDateForInput(new Date());
        document.getElementById('fReceivedTime').value = parseTimeToInput(request.ReceivedTime) || formatTimeForInput(new Date());
        if (document.getElementById('fEstimateDate')) {
          document.getElementById('fEstimateDate').value = parseDateToInput(request.EstimateDate) || '';
        }
        if (document.getElementById('fEstimateTime')) {
          document.getElementById('fEstimateTime').value = parseTimeToInput(request.EstimateTime) || '';
        }
        document.getElementById('fReceivedBy').value = request.ReceivedBy || currentUser.fullName || '';
        document.getElementById('fWorkOrderNo').value = request.WorkOrderNo || '';
        document.getElementById('fStatus').value = request.Status || 'รอดำเนินการ';
      } else {
        document.getElementById('section2').style.display = 'none';
      }

      showPage('formPage');
    })
    .withFailureHandler(function(error) {
      hideLoading();
      showToast('ไม่สามารถโหลดข้อมูลได้: ' + error.message, 'error');
    })
    .getRequestByUUID(uuid);
}

function setFormFieldsEditable(editable) {
  const fields = ['fInformDate', 'fInformTime',
                  'fEquipmentCode', 'fHrKm', 'fDueDate', 'fDamageAppearance',
                  'fRequesterName', 'fApproverName', 'fApproverTel'];
  fields.forEach(function(id) {
    const el = document.getElementById(id);
    if (el) el.readOnly = !editable;
  });
  // fEquipmentName is read-only (auto-populated from equipment code)
  const eqNameEl = document.getElementById('fEquipmentName');
  if (eqNameEl) eqNameEl.readOnly = true;
  // fRequestId is read-only (auto-generated by system)
  const reqIdEl = document.getElementById('fRequestId');
  if (reqIdEl) reqIdEl.readOnly = true;
}

/**
 * handleWorkOrderInput - ตรวจจับและบังคับให้กรอกได้เฉพาะตัวเลข (0-9) เท่านั้น
 * พร้อมเปลี่ยนสถานะเป็น "กำลังซ่อม" ทันทีถ้าสถานะเดิมเป็น "รอดำเนินการ"
 */
function handleWorkOrderInput() {
  const woEl = document.getElementById('fWorkOrderNo');
  if (!woEl) return;

  // กรองตัวอักษรและอักขระพิเศษออกทันที ให้เหลือเฉพาะตัวเลข 0-9 เท่านั้น
  const raw = woEl.value;
  const filtered = raw.replace(/\D/g, '');
  if (raw !== filtered) {
    woEl.value = filtered;
  }

  const statusEl = document.getElementById('fStatus');
  if (!statusEl) return;
  const woVal = woEl.value.trim();
  if (woVal !== '' && statusEl.value === 'รอดำเนินการ') {
    statusEl.value = 'กำลังซ่อม';
    statusEl.style.transition = 'all 0.3s ease';
    statusEl.style.borderColor = '#2563EB';
    statusEl.style.boxShadow = '0 0 0 3px rgba(37, 99, 235, 0.2)';
    setTimeout(function() {
      statusEl.style.borderColor = '';
      statusEl.style.boxShadow = '';
    }, 1200);
  }
}


function handleSaveRequest() {
  // Validate required fields
  const equipmentCode = document.getElementById('fEquipmentCode').value.trim();
  let equipmentName = document.getElementById('fEquipmentName').value.trim();
  let informDate = document.getElementById('fInformDate').value;
  let informTime = document.getElementById('fInformTime').value;
  const damageAppearance = document.getElementById('fDamageAppearance').value.trim();

  const now = new Date();
  if (!informDate) {
    informDate = formatDateForInput(now);
    document.getElementById('fInformDate').value = informDate;
  }
  if (!informTime) {
    informTime = formatTimeForInput(now);
    document.getElementById('fInformTime').value = informTime;
  }

  if (!equipmentCode) {
    showToast('กรุณาระบุรหัสอุปกรณ์', 'error');
    document.getElementById('fEquipmentCode').focus();
    return;
  }

  // หากข้อมูล GSE Master ยังไม่พร้อม ให้โหลดแล้วทำรายการต่อ
  if (equipmentMasterList === null) {
    showLoading();
    loadEquipmentMaster(function() {
      hideLoading();
      handleSaveRequest();
    });
    return;
  }

  const warnEl = document.getElementById('equipmentInactiveWarning');
  const codeInput = document.getElementById('fEquipmentCode');

  // ตรวจสอบว่ารหัสอุปกรณ์มีใน sheet GSE MASTER หรือไม่
  const matchedEquipment = findEquipmentInMaster(equipmentCode);
  if (!matchedEquipment) {
    showToast('ไม่มีในระบบ ไม่สามารถแจ้งซ่อมอุปกรณ์ดังกล่าวได้', 'error');
    if (warnEl) {
      warnEl.innerHTML = '<i class="fas fa-exclamation-triangle"></i> รหัสอุปกรณ์ <strong>' + escapeHtml(equipmentCode) + '</strong> ไม่มีในระบบ ไม่สามารถแจ้งซ่อมอุปกรณ์ดังกล่าวได้';
      warnEl.style.display = 'flex';
    }
    if (codeInput) {
      codeInput.focus();
      codeInput.style.borderColor = '#EF4444';
      codeInput.style.boxShadow = '0 0 0 3px rgba(239, 68, 68, 0.15)';
    }
    return;
  }

  // อัพเดตรหัสและชื่อทางการตาม GSE MASTER
  if (warnEl) warnEl.style.display = 'none';
  if (codeInput) {
    codeInput.style.borderColor = '';
    codeInput.style.boxShadow = '';
    codeInput.value = matchedEquipment.gseNo;
  }
  equipmentName = matchedEquipment.description || matchedEquipment.gseNo;
  document.getElementById('fEquipmentName').value = equipmentName;

  if (!damageAppearance) {
    showToast('กรุณากรอกอาการเสีย', 'error');
    document.getElementById('fDamageAppearance').focus();
    return;
  }

  const data = {
    informDate: informDate,
    informTime: informTime,
    equipmentName: equipmentName,
    equipmentCode: matchedEquipment.gseNo,
    hrKm: document.getElementById('fHrKm').value.trim(),
    dueDate: document.getElementById('fDueDate').value,
    damageAppearance: damageAppearance,
    requesterName: document.getElementById('fRequesterName').value.trim(),
    requesterId: document.getElementById('fRequesterId').value.trim(),
    approverName: document.getElementById('fApproverName').value.trim(),
    approverTel: document.getElementById('fApproverTel').value.trim()
  };

  // Admin fields
  if (currentUser.role === 'admin') {
    data.requestId = document.getElementById('fRequestId').value.trim();
    data.status = document.getElementById('fStatus').value;
    data.receivedDate = document.getElementById('fReceivedDate').value;
    data.receivedTime = document.getElementById('fReceivedTime').value;
    data.estimateDate = formatDateDMY(document.getElementById('fEstimateDate') ? document.getElementById('fEstimateDate').value : '');
    data.estimateTime = document.getElementById('fEstimateTime') ? document.getElementById('fEstimateTime').value : '';
    data.receivedBy = document.getElementById('fReceivedBy').value.trim();

    // ตรวจสอบและกรอง W/O ให้เป็นตัวเลขเท่านั้น (ห้ามมีตัวอักษรหรือข้อความ)
    const rawWo = document.getElementById('fWorkOrderNo') ? document.getElementById('fWorkOrderNo').value.trim() : '';
    if (rawWo && !/^\d+$/.test(rawWo)) {
      showToast('เลขที่ใบสั่งงาน (W/O) ต้องเป็นตัวเลขเท่านั้น (ห้ามใส่ตัวอักษรหรือข้อความ)', 'error');
      const woEl = document.getElementById('fWorkOrderNo');
      if (woEl) {
        woEl.value = rawWo.replace(/\D/g, '');
        woEl.focus();
      }
      return;
    }
    data.workOrderNo = rawWo.replace(/\D/g, '');

    // ถ้ามีการใส่ W/O แล้วสถานะยังเป็น "รอดำเนินการ" ให้ปรับเป็น "กำลังซ่อม" ทันที
    if (data.workOrderNo && data.status === 'รอดำเนินการ') {
      data.status = 'กำลังซ่อม';
    }
  }

  const mode = document.getElementById('formMode').value;
  const uuid = document.getElementById('formUUID').value;

  // ตรวจสอบว่าอุปกรณ์เป็น Inactive หรือไม่ (ห้ามแจ้งซ่อม)
  const isInactive = isEquipmentInactive(matchedEquipment.gseNo) || matchedEquipment.isInactive;
  if (currentUser.role !== 'admin' && isInactive) {
    showToast('อุปกรณ์รหัส ' + matchedEquipment.gseNo + ' มีสถานะ Inactive ไม่สามารถแจ้งซ่อมได้', 'error');
    if (warnEl) {
      warnEl.innerHTML = '<i class="fas fa-ban"></i> อุปกรณ์ <strong>' + escapeHtml(matchedEquipment.gseNo) + '</strong> มีสถานะ Inactive ไม่สามารถแจ้งซ่อมได้';
      warnEl.style.display = 'flex';
    }
    if (codeInput) codeInput.focus();
    return;
  }

  // ตรวจสอบ duplicate เฉพาะตอน create และมีรหัสอุปกรณ์
  if (mode === 'create' && matchedEquipment.gseNo) {
    showLoading();
    google.script.run
      .withSuccessHandler(function(result) {
        hideLoading();
        if (result.hasDuplicate) {
          showDuplicateModal(equipmentCode, result.existingRequests, data, mode, uuid);
        } else {
          doSaveRequest(data, mode, uuid);
        }
      })
      .withFailureHandler(function() {
        hideLoading();
        doSaveRequest(data, mode, uuid); // ถ้า check ไม่ได้ก็ save เลย
      })
      .checkDuplicateEquipment(equipmentCode, '');
  } else {
    doSaveRequest(data, mode, uuid);
  }
}

/**
 * ทำการ save จริง (create หรือ update) — อัปเดต local cache แทน full reload
 */
function doSaveRequest(data, mode, uuid) {
  showLoading();

  if (mode === 'create') {
    google.script.run
      .withSuccessHandler(function(result) {
        hideLoading();
        if (result.success) {
          showToast(result.message, 'success');
          document.getElementById('navUserName').textContent = currentUser.fullName;
          showPage('dashboardPage');
          loadDashboardData(true);
        } else {
          showToast(result.message, 'error');
        }
      })
      .withFailureHandler(function(error) {
        hideLoading();
        showToast('เกิดข้อผิดพลาด: ' + error.message, 'error');
      })
      .createRequest(data);
  } else {
    google.script.run
      .withSuccessHandler(function(result) {
        hideLoading();
        if (result.success) {
          showToast(result.message, 'success');
          showPage('dashboardPage');
          loadDashboardData(true);
        } else {
          showToast(result.message, 'error');
        }
      })
      .withFailureHandler(function(error) {
        hideLoading();
        showToast('เกิดข้อผิดพลาด: ' + error.message, 'error');
      })
      .updateRequest(uuid, data, currentUser.role, (currentUser.role === 'admin' ? currentUser.employeeId : null));
  }
}


// === DELETE ===
let deleteTargetRequestId = null;

function showDeleteModal(uuid, requestId) {
  deleteTarget = (uuid && uuid !== 'undefined') ? uuid : '';
  deleteTargetRequestId = (requestId && requestId !== 'undefined') ? requestId : '';
  document.getElementById('deleteModalInfo').textContent =
    'เลขที่ใบแจ้งซ่อม: ' + (requestId || uuid || 'ไม่ระบุ');
  document.getElementById('deleteModal').style.display = 'flex';
}

function closeDeleteModal() {
  deleteTarget = null;
  deleteTargetRequestId = null;
  document.getElementById('deleteModal').style.display = 'none';
}

function confirmDelete() {
  if (!deleteTarget && !deleteTargetRequestId) return;

  const targetUuid = deleteTarget;
  const targetReqId = deleteTargetRequestId;

  showLoading();
  closeDeleteModal();

  google.script.run
    .withSuccessHandler(function(result) {
      hideLoading();
      if (result.success) {
        showToast(result.message, 'success');
        loadDashboardData(true);
      } else {
        showToast(result.message, 'error');
      }
    })
    .withFailureHandler(function(error) {
      hideLoading();
      showToast('เกิดข้อผิดพลาด: ' + error.message, 'error');
    })
    .deleteRequest(targetUuid, targetReqId);
}

// === RESET WORK ORDER (TECHNICIAN / ADMIN) ===
function openResetModal(uuid, eqCode, woNo) {
  const modal = document.getElementById('resetWorkOrderModal');
  const uuidInput = document.getElementById('resetModalUUID');
  const reasonInput = document.getElementById('resetWorkOrderReason');
  if (uuidInput) uuidInput.value = uuid || '';
  if (reasonInput) reasonInput.value = '';
  if (modal) modal.style.display = 'flex';
}

function closeResetModal() {
  const modal = document.getElementById('resetWorkOrderModal');
  const reasonInput = document.getElementById('resetWorkOrderReason');
  if (reasonInput) reasonInput.value = '';
  if (modal) modal.style.display = 'none';
}

function handleConfirmResetWorkOrder() {
  const uuid = (document.getElementById('resetModalUUID') ? document.getElementById('resetModalUUID').value : '').trim();
  const reason = (document.getElementById('resetWorkOrderReason') ? document.getElementById('resetWorkOrderReason').value : '').trim();
  const userEmpId = currentUser ? (currentUser.employeeId || '') : '';

  if (!uuid) {
    showToast('ไม่พบรหัสใบงานที่ต้องการรีเซ็ต', 'error');
    return;
  }
  if (!reason) {
    showToast('กรุณาระบุเหตุผลที่ต้องการรีเซ็ตใบงาน', 'error');
    if (document.getElementById('resetWorkOrderReason')) {
      document.getElementById('resetWorkOrderReason').focus();
    }
    return;
  }

  showLoading();
  closeResetModal();

  google.script.run
    .withSuccessHandler(function(res) {
      hideLoading();
      if (res && res.success) {
        showToast(res.message || 'รีเซ็ตใบงานเรียบร้อยแล้ว', 'success');
        loadDashboardData(true);
      } else {
        showToast((res && res.message) ? res.message : 'เกิดข้อผิดพลาดในการรีเซ็ตใบงาน', 'error');
      }
    })
    .withFailureHandler(function(err) {
      hideLoading();
      showToast('เกิดข้อผิดพลาด: ' + (err.message || err), 'error');
    })
    .resetTechnicianReport(uuid, userEmpId, reason);
}

// === RESTORE / SYNC WO MODAL (Admin) ===
function openRestoreWoModal() {
  const modal = document.getElementById('restoreWoModal');
  if (!modal) return;
  const now = new Date();
  const currentMonth = now.getMonth() + 1; // 1-12
  const currentYear = now.getFullYear();

  const monthSelect = document.getElementById('restoreWoMonth');
  const yearSelect = document.getElementById('restoreWoYear');
  if (monthSelect) monthSelect.value = currentMonth;
  if (yearSelect) yearSelect.value = currentYear;

  modal.style.display = 'flex';
}

function closeRestoreWoModal() {
  const modal = document.getElementById('restoreWoModal');
  if (modal) modal.style.display = 'none';
}

function handleConfirmRestoreWo() {
  const monthSelect = document.getElementById('restoreWoMonth');
  const yearSelect = document.getElementById('restoreWoYear');
  const monthNum = monthSelect ? monthSelect.value : '';
  const yearNum = yearSelect ? yearSelect.value : '';

  if (!monthNum || !yearNum) {
    showToast('กรุณาเลือกเดือนและปี', 'error');
    return;
  }

  const btn = document.getElementById('btnConfirmRestoreWo');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> กำลังกู้คืนข้อมูล...';
  }

  showLoading();
  google.script.run
    .withSuccessHandler(function(result) {
      hideLoading();
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = '<i class="fas fa-sync-alt"></i> เริ่มกู้คืน / ซิงค์ข้อมูล';
      }
      if (result.success) {
        showToast(result.message, 'success');
        closeRestoreWoModal();
        loadDashboardData(true);
      } else {
        showToast(result.message, 'error');
      }
    })
    .withFailureHandler(function(error) {
      hideLoading();
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = '<i class="fas fa-sync-alt"></i> เริ่มกู้คืน / ซิงค์ข้อมูล';
      }
      showToast('เกิดข้อผิดพลาด: ' + (error.message || error), 'error');
    })
    .adminRestoreWoMonthSheet(monthNum, yearNum, (currentUser ? currentUser.employeeId : ''));
}

// === PRINT VIEW & LAZY TEMPLATE LOADER ===
let isPdfTemplateLoaded = false;
let isPdfTemplateLoading = false;

function ensurePdfTemplateLoaded(callback) {
  if (isPdfTemplateLoaded || document.getElementById('pdfTemplateStyleTag')) {
    isPdfTemplateLoaded = true;
    if (callback) callback();
    return;
  }

  // 1. ตรวจสอบใน sessionStorage ก่อนเพื่อประหยัด Network Request
  try {
    const cachedCss = sessionStorage.getItem('cached_pdf_template_css');
    if (cachedCss) {
      injectPdfTemplateStyle(cachedCss);
      isPdfTemplateLoaded = true;
      if (callback) callback();
      return;
    }
  } catch(e) {}

  if (isPdfTemplateLoading) {
    setTimeout(function() { ensurePdfTemplateLoaded(callback); }, 150);
    return;
  }

  isPdfTemplateLoading = true;
  google.script.run
    .withSuccessHandler(function(cssContent) {
      isPdfTemplateLoading = false;
      if (cssContent) {
        injectPdfTemplateStyle(cssContent);
        try {
          sessionStorage.setItem('cached_pdf_template_css', cssContent);
        } catch(e) {}
      }
      isPdfTemplateLoaded = true;
      if (callback) callback();
    })
    .withFailureHandler(function(err) {
      isPdfTemplateLoading = false;
      console.warn('Lazy loading PDF template warning:', err);
      if (callback) callback();
    })
    .getPdfTemplateCss();
}

function injectPdfTemplateStyle(htmlOrCss) {
  if (!htmlOrCss || document.getElementById('pdfTemplateStyleTag')) return;
  const container = document.createElement('div');
  container.id = 'pdfTemplateStyleTag';
  container.innerHTML = htmlOrCss;
  document.head.appendChild(container);
}

function showPrintView(uuid) {
  showLoading();

  // โหลดรูปฟอร์มพิมพ์แบบ Lazy-load ทันทีที่กดพิมพ์
  ensurePdfTemplateLoaded();

  google.script.run
    .withSuccessHandler(function(request) {
      hideLoading();
      if (!request) {
        showToast('ไม่พบข้อมูลใบแจ้งซ่อม', 'error');
        return;
      }

      // เติมข้อมูลในหน้า print (ตรงตามตำแหน่งฟอร์ม PDF ต้นฉบับ)
      setDateFields('pInformDate', request.InformDate);
      setText('pInformTime', cleanDisplayTime(request.InformTime));
      setText('pEquipmentName', request.EquipmentName);
      setText('pEquipmentCode', request.EquipmentCode);
      setText('pHrKm', request.HrKm);
      setDateFields('pDueDate', request.DueDate);
      setText('pDamageAppearance', request.DamageAppearance);
      setPdfFieldFit('pRequesterName', request.RequesterName, 11.5, 8.5);
      setText('pRequesterId', request.RequesterID);
      setPdfFieldFit('pApproverName', request.ApproverName, 11.5, 8.5);
      setText('pApproverTel', request.ApproverTel);
      setDateFields('pReceivedDate', request.ReceivedDate);
      setText('pReceivedTime', cleanDisplayTime(request.ReceivedTime));
      setPdfFieldFit('pReceivedBy', request.ReceivedBy, 12, 8.5);
      setText('pWorkOrderNo', request.WorkOrderNo);
      setText('pEstimateDate', formatDateDMY(request.EstimateDate));
      setText('pEstimateTime', cleanDisplayTime(request.EstimateTime));

      // เติมข้อมูลงานช่าง (ส่วน 2.1 และผู้ปฏิบัติงาน)
      setDateFields('pCompleteDate', request.CompleteDate);
      setText('pCompleteTime', cleanDisplayTime(request.CompleteTime));
      setText('pMaintenanceDetails', request.MaintenanceDetails);
      setText('pActionBy1', request.ActionBy1);
      setText('pActionBy2', request.ActionBy2);
      setText('pActionBy3', request.ActionBy3);
      setText('pActualRepairTime', request.ActualRepairTime);

      // เติมข้อมูลกล่อง 2.1 Supervisor Approved
      setText('pSupervisorApprovedSign', request.SupervisorName);
      setText('pSupervisorApprovedName', request.SupervisorName || '');
      setDateFields('pSupervisorApprovedDate', request.SupervisorDate);
      setText('pSupervisorApprovedTime', cleanDisplayTime(request.SupervisorTime));

      // เติมข้อมูลส่วนลงนาม 4 ช่องล่าง (Bottom Endorsement Boxes)
      // Box 1: ผู้รับรอง (Admited By - ผู้รับมอบอุปกรณ์)
      setText('pAdmitedByName', request.AcceptedByName);
      setDateFields('pAdmitedDate', request.AcceptedDate);
      setText('pAdmitedTime', cleanDisplayTime(request.AcceptedTime));

      // Box 2: ผู้ซ่อม (Corrected By)
      setText('pCorrectedByName', request.TechnicianName);
      setDateFields('pCorrectedDate', request.TechnicianDate || request.CompleteDate);
      setText('pCorrectedTime', cleanDisplayTime(request.TechnicianTime || request.CompleteTime));

      // Box 3: ผู้ตรวจสอบ (Checked By - Supervisor)
      setText('pCheckedByName', request.SupervisorName);
      setDateFields('pCheckedDate', request.SupervisorDate);
      setText('pCheckedTime', cleanDisplayTime(request.SupervisorTime));

      // Box 4: ผู้อนุมัติ (Approved By - Manager)
      setText('pApprovedByName', request.ManagerName);
      setDateFields('pApprovedDate', request.ManagerDate);
      setText('pApprovedTime', cleanDisplayTime(request.ManagerTime));

      // ล้างและเติมข้อมูลอะไหล่ที่เปลี่ยน (แถว 1-4)
      for (var r = 1; r <= 4; r++) {
        setText('pPartRow' + r + '_Name', '');
        setText('pPartRow' + r + '_No', '');
        setText('pPartRow' + r + '_Type', '');
        setText('pPartRow' + r + '_Qty', '');
        setText('pPartRow' + r + '_Price', '');
      }

      var parts = request.spareParts || [];
      for (var p = 0; p < parts.length && p < 4; p++) {
        var rowNum = p + 1;
        setText('pPartRow' + rowNum + '_Name', parts[p].sparePartName);
        setText('pPartRow' + rowNum + '_No', parts[p].partNo);
        setText('pPartRow' + rowNum + '_Type', parts[p].typeModel);
        setText('pPartRow' + rowNum + '_Qty', parts[p].qty);
        setText('pPartRow' + rowNum + '_Price', parts[p].price);
      }

      showPage('printPage');
      setupPrintPinchZoom();
      setTimeout(fitPrintToScreen, 50);
      setTimeout(fitPrintToScreen, 200);

      // อัปเดตสถานะปริ้นท์ใน Sheet "บันทึกการเปิด W/O" เป็น "Printed" อัตโนมัติ
      google.script.run.markRequestPrinted(uuid);
    })
    .withFailureHandler(function(error) {
      hideLoading();
      showToast('ไม่สามารถโหลดข้อมูลได้: ' + error.message, 'error');
    })
    .getRequestByUUID(uuid);
}

// === PRINT VIEW ZOOM & PINCH ===
let printCurrentScale = 1.0;
const PRINT_BASE_W = 794;
const PRINT_BASE_H = 1027;

function setPrintScale(scale, animated) {
  const clamped = Math.min(2.5, Math.max(0.35, Math.round(scale * 100) / 100));
  printCurrentScale = clamped;

  const scaler = document.getElementById('printViewportScaler');
  const page = document.getElementById('printPdfPage');
  const badge = document.getElementById('printZoomBadge');

  if (badge) {
    badge.textContent = Math.round(clamped * 100) + '%';
  }

  if (scaler && page) {
    scaler.style.transition = animated ? 'width 0.15s ease-out, height 0.15s ease-out' : 'none';
    page.style.transition = animated ? 'transform 0.15s ease-out' : 'none';

    scaler.style.width = Math.round(PRINT_BASE_W * clamped) + 'px';
    scaler.style.height = Math.round(PRINT_BASE_H * clamped) + 'px';
    page.style.transform = 'scale(' + clamped + ')';
  }
}

function adjustPrintZoom(delta) {
  setPrintScale(printCurrentScale + delta, true);
}

function resetPrintZoom() {
  setPrintScale(1.0, true);
}

function fitPrintToScreen() {
  const container = document.getElementById('printOuterContainer');
  if (!container) return;
  const winW = window.innerWidth || document.documentElement.clientWidth || 390;
  const containerW = container.clientWidth || winW;
  const padding = 16;
  const availW = Math.min(containerW, winW) - padding;
  if (availW <= 0) return;
  const targetScale = Math.min(1.0, availW / PRINT_BASE_W);
  setPrintScale(Math.max(0.3, targetScale), true);
}

let initialPinchDistance = null;
let initialScaleOnPinch = 1.0;

function setupPrintPinchZoom() {
  const container = document.getElementById('printOuterContainer');
  if (!container || container._hasPinchAttached) return;
  container._hasPinchAttached = true;

  container.addEventListener('touchstart', function(e) {
    if (e.touches && e.touches.length === 2) {
      initialPinchDistance = Math.hypot(
        e.touches[0].clientX - e.touches[1].clientX,
        e.touches[0].clientY - e.touches[1].clientY
      );
      initialScaleOnPinch = printCurrentScale;
    }
  }, { passive: true });

  container.addEventListener('touchmove', function(e) {
    if (e.touches && e.touches.length === 2 && initialPinchDistance) {
      if (e.cancelable) e.preventDefault();
      const dist = Math.hypot(
        e.touches[0].clientX - e.touches[1].clientX,
        e.touches[0].clientY - e.touches[1].clientY
      );
      const factor = dist / initialPinchDistance;
      setPrintScale(initialScaleOnPinch * factor, false);
    }
  }, { passive: false });

  container.addEventListener('touchend', function(e) {
    if (!e.touches || e.touches.length < 2) {
      initialPinchDistance = null;
    }
  }, { passive: true });

  window.addEventListener('resize', function() {
    const page = document.getElementById('printPage');
    if (page && page.classList.contains('active')) {
      fitPrintToScreen();
    }
  });
}

// === HELPER FUNCTIONS ===
function setText(id, value) {
  const el = document.getElementById(id);
  if (el) el.textContent = value || '';
}

function setPdfFieldFit(id, text, maxFontSize, minFontSize) {
  const el = document.getElementById(id);
  if (!el) return;
  maxFontSize = maxFontSize || 11.5;
  minFontSize = minFontSize || 8.0;
  el.textContent = text || '';
  el.style.fontSize = maxFontSize + 'px';
  // Allow DOM to render then adjust if overflowing
  setTimeout(function() {
    if (el && el.offsetWidth > 0) {
      let size = maxFontSize;
      while (el.scrollWidth > el.offsetWidth && size > minFontSize) {
        size -= 0.5;
        el.style.fontSize = size + 'px';
      }
    }
  }, 10);
}

function setDateFields(prefix, dateVal) {
  if (!dateVal) {
    setText(prefix + 'Day', '');
    setText(prefix + 'Month', '');
    setText(prefix + 'Year', '');
    return;
  }
  const s = dateVal.toString().trim();
  if (s.indexOf('1899') !== -1) {
    setText(prefix + 'Day', '');
    setText(prefix + 'Month', '');
    setText(prefix + 'Year', '');
    return;
  }
  let day = '', month = '', year = '';
  if (s.indexOf('/') !== -1) {
    const parts = s.split('/');
    if (parts.length === 3) {
      day = parts[0];
      month = parts[1];
      year = parts[2];
    }
  } else if (s.indexOf('-') !== -1) {
    const parts = s.split('-');
    if (parts.length === 3) {
      year = parts[0];
      month = parts[1];
      day = parts[2];
    }
  }
  setText(prefix + 'Day', day);
  setText(prefix + 'Month', month);
  setText(prefix + 'Year', year);
}

function escapeHtml(text) {
  if (text === null || text === undefined) return '';
  const div = document.createElement('div');
  div.textContent = String(text);
  return div.innerHTML;
}

function formatDateForInput(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return year + '-' + month + '-' + day;
}

function formatTimeForInput(date) {
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  return hours + ':' + minutes;
}

function parseDateToInput(dateStr) {
  if (!dateStr) return '';
  // ถ้าเป็น format dd/MM/yyyy
  if (typeof dateStr === 'string' && dateStr.indexOf('/') !== -1) {
    const parts = dateStr.split('/');
    if (parts.length === 3) {
      return parts[2] + '-' + parts[1].padStart(2, '0') + '-' + parts[0].padStart(2, '0');
    }
  }
  // ถ้าเป็น format yyyy-MM-dd
  if (typeof dateStr === 'string' && dateStr.indexOf('-') !== -1) {
    return dateStr;
  }
  return dateStr.toString();
}

function normalizeTo24Hour(timeStr) {
  if (!timeStr) return '';
  const s = timeStr.toString().trim();
  if (s.indexOf('1899') !== -1) return '';

  // ตรวจจับ 12-hour AM/PM (เช่น "5:30 PM", "05:30:00 PM", "5:30am")
  const ampmMatch = s.match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*([AaPp][Mm])?$/);
  if (ampmMatch) {
    let hours = parseInt(ampmMatch[1], 10);
    const minutes = ampmMatch[2];
    const modifier = ampmMatch[3] ? ampmMatch[3].toUpperCase() : null;

    if (modifier === 'PM' && hours < 12) {
      hours += 12;
    } else if (modifier === 'AM' && hours === 12) {
      hours = 0;
    }
    return String(hours).padStart(2, '0') + ':' + minutes;
  }

  // กรณี 24-hour (เช่น "17:30", "17:30:00", "7:30")
  const match = s.match(/^(\d{1,2}):(\d{2})/);
  if (match) {
    const hours = parseInt(match[1], 10);
    const minutes = match[2];
    return String(hours).padStart(2, '0') + ':' + minutes;
  }
  return '';
}

function parseTimeToInput(timeStr) {
  return normalizeTo24Hour(timeStr);
}

function cleanDisplayDate(val) {
  if (!val) return '';
  const s = val.toString().trim();
  if (s.indexOf('1899') !== -1) return '';
  return s;
}

/**
 * formatDateDMY - แปลงวันที่เป็นรูปแบบ วัน/เดือน/ปี (dd/MM/yyyy) เสมอ
 */
function formatDateDMY(val) {
  if (!val) return '';
  const s = val.toString().trim();
  if (s.indexOf('1899') !== -1) return '';
  const isoMatch = s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
  if (isoMatch) {
    return isoMatch[3].padStart(2, '0') + '/' + isoMatch[2].padStart(2, '0') + '/' + isoMatch[1];
  }
  const dmyMatch = s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/);
  if (dmyMatch) {
    return dmyMatch[1].padStart(2, '0') + '/' + dmyMatch[2].padStart(2, '0') + '/' + dmyMatch[3];
  }
  return s;
}

function cleanDisplayTime(val) {
  return normalizeTo24Hour(val);
}

// ============================================================
// === EQUIPMENT AUTOCOMPLETE ===
// ============================================================
let equipmentMasterList = null; // cache
let _pendingSaveData = null;    // เก็บ data ชั่วคราวระหว่างรอ confirm duplicate

/**
 * รายการรหัสอุปกรณ์ที่มีสถานะ Inactive (ห้ามแจ้งซ่อม)
 */
const INACTIVE_EQUIPMENTS = [
  'TLM-BC-011', 'TLM-BC-012', 'TLM-BC-013', 'TLM-BC-027', 'TLM-BC-028', 'TLM-BC-029',
  'TLM-BC-055', 'TLM-BC-058', 'TLM-BC-061', 'TLM-BC-090', 'TLM-BC-091', 'TLM-BC-092',
  'TLM-BC-093', 'TLM-BC-094', 'TLM-BC-105', 'TLM-BC-106', 'TLM-BC-119', 'TLM-BC-123',
  'TLM-BC-134', 'TLM-BC-145', 'TLM-BC-160', 'TLM-BC-168', 'TLM-BC-216', 'TLM-BC-226',
  'TLM-BC-229', 'TLM-BC-231', 'TLM-BC-236', 'TLM-BC-239', 'TLM-BC-240', 'TLM-BC-254',
  'TLM-BC-255', 'TLM-BC-256', 'TLM-BC-265', 'TLM-BC-282', 'TLM-BC-287',
  'TLM-ES-053', 'TLM-ES-054', 'TLM-ES-055',
  'TLM-N2-002',
  'TLM-PB-002', 'TLM-PB-028', 'TLM-PB-029',
  'TLM-PS-019', 'TLM-PS-020', 'TLM-PS-061', 'TLM-PS-062', 'TLM-PS-063', 'TLM-PS-066', 'TLM-PS-067',
  'TLM-PU-040',
  'TLM-TB-006', 'TLM-TB-007', 'TLM-TB-008', 'TLM-TB-039',
  'TLM-TR-043', 'TLM-TR-044', 'TLM-TR-045', 'TLM-TR-046', 'TLM-TR-047', 'TLM-TR-048',
  'TLM-VP-003'
];

/**
 * ค้นหาข้อมูลอุปกรณ์ใน GSE MASTER ตามรหัส (Normalized เพื่อความยืดหยุ่น)
 * @param {string} equipmentCode
 * @returns {Object|null}
 */
function findEquipmentInMaster(equipmentCode) {
  if (!equipmentCode) return null;
  const norm = equipmentCode.toString().toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!norm) return null;
  const list = (typeof equipmentMasterList !== 'undefined' && Array.isArray(equipmentMasterList)) ? equipmentMasterList : [];
  for (let i = 0; i < list.length; i++) {
    const itemNorm = (list[i].gseNo || '').toString().toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (norm === itemNorm) {
      return list[i];
    }
  }
  return null;
}

function isEquipmentInactive(code) {
  if (!code) return false;
  const norm = code.toString().toUpperCase().replace(/[^A-Z0-9]/g, '');

  // 1. ตรวจจาก equipmentMasterList ที่ดึงสดจากชีต Emro Status ก่อนเป็นหลัก
  if (equipmentMasterList && equipmentMasterList.length > 0) {
    for (let i = 0; i < equipmentMasterList.length; i++) {
      const itemNorm = (equipmentMasterList[i].gseNo || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
      if (norm === itemNorm) {
        return !!equipmentMasterList[i].isInactive;
      }
    }
  }

  // 2. Fallback: รายการคงที่เดิม
  for (let i = 0; i < INACTIVE_EQUIPMENTS.length; i++) {
    if (norm === INACTIVE_EQUIPMENTS[i].replace(/[^A-Z0-9]/g, '')) return true;
  }
  return false;
}

/**
 * โหลด equipment list จาก server (พร้อมตัวเลือกรีเฟรชสด)
 */
function loadEquipmentMaster(callback, forceRefresh) {
  if (equipmentMasterList !== null && !forceRefresh) {
    if (callback) callback();
    return;
  }
  google.script.run
    .withSuccessHandler(function(list) {
      equipmentMasterList = list || [];
      if (callback) callback();
    })
    .withFailureHandler(function() {
      equipmentMasterList = equipmentMasterList || [];
      if (callback) callback();
    })
    .getEquipmentList(!!forceRefresh);
}

/**
 * escape ค่า string สำหรับใส่ใน HTML attribute (ป้องกัน double-quote พัง และรองรับ number/null ปลอดภัย 100%)
 */
function escapeAttr(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/**
 * เมื่อ user พิมพ์ในช่อง Equipment Code → filter และแสดง dropdown
 */
function onEquipmentCodeInput(val) {
  const query = val.trim().toUpperCase();
  const dropdown = document.getElementById('equipmentDropdown');
  const warnEl = document.getElementById('equipmentInactiveWarning');
  const codeInput = document.getElementById('fEquipmentCode');

  // ล้างสถานะกรอบสีแดงเมื่อผู้ใช้เริ่มพิมพ์แก้ไข
  if (codeInput) {
    codeInput.style.borderColor = '';
    codeInput.style.boxShadow = '';
  }

  // ตรวจสอบเบื้องต้น: ถ้ารหัสตรงกับ Inactive ในระบบ ให้เตือน
  if (isEquipmentInactive(val)) {
    if (warnEl) {
      warnEl.innerHTML = '<i class="fas fa-ban"></i> รหัสอุปกรณ์ <strong>' + escapeHtml(val.trim().toUpperCase()) + '</strong> มีสถานะ Inactive ไม่สามารถแจ้งซ่อมได้';
      warnEl.style.display = 'flex';
    }
  } else {
    // ถ้ากำลังพิมพ์แก้ไขและยังไม่ตรง ให้ซ่อนคำเตือนชั่วคราว
    if (warnEl) warnEl.style.display = 'none';
  }

  if (!query) {
    const nameEl = document.getElementById('fEquipmentName');
    if (nameEl) nameEl.value = '';
    dropdown.style.display = 'none';
    return;
  }
  if (query.length < 2) {
    dropdown.style.display = 'none';
    return;
  }

  if (equipmentMasterList === null) {
    dropdown.innerHTML = '<div class="equipment-dropdown-empty">กำลังโหลดข้อมูลอุปกรณ์...</div>';
    dropdown.style.display = 'block';
    loadEquipmentMaster(function() {
      onEquipmentCodeInput(val); // re-run after loaded
    });
    return;
  }

  // filter
  const filtered = equipmentMasterList.filter(function(item) {
    return item.gseNo.toUpperCase().indexOf(query) !== -1 ||
           item.description.toUpperCase().indexOf(query) !== -1;
  }).slice(0, 15); // แสดงสูงสุด 15 รายการ

  if (filtered.length === 0) {
    dropdown.innerHTML = '<div class="equipment-dropdown-empty"><i class="fas fa-exclamation-circle"></i> ไม่พบรหัสอุปกรณ์นี้ใน sheet GSE MASTER</div>';
    dropdown.style.display = 'block';
    return;
  }

  // ใช้ data-gse / data-desc / data-inactive
  dropdown.innerHTML = filtered.map(function(item) {
    const isInactive = isEquipmentInactive(item.gseNo) || item.isInactive;
    const codeHl = highlightMatch(escapeHtml(item.gseNo), query);
    const descHl = highlightMatch(escapeHtml(item.description), query);

    if (isInactive) {
      return '<div class="equipment-dropdown-item item-inactive" ' +
             'data-gse="' + escapeAttr(item.gseNo) + '" ' +
             'data-desc="' + escapeAttr(item.description) + '" ' +
             'data-inactive="true" ' +
             'onmousedown="selectEquipmentFromEl(this)">' +
             '<div class="eq-header-row">' +
             '  <div class="eq-code" style="color:#64748B;">' + codeHl + '</div>' +
             '  <span class="badge-inactive"><i class="fas fa-ban"></i> INACTIVE</span>' +
             '</div>' +
             '<div class="eq-desc" style="color:#94A3B8;">' + descHl + '</div>' +
             '<div class="eq-inactive-note"><i class="fas fa-exclamation-triangle"></i> อุปกรณ์นี้มีสถานะ Inactive ไม่สามารถแจ้งซ่อมได้</div>' +
             '</div>';
    }

    return '<div class="equipment-dropdown-item" ' +
           'data-gse="' + escapeAttr(item.gseNo) + '" ' +
           'data-desc="' + escapeAttr(item.description) + '" ' +
           'data-inactive="false" ' +
           'onmousedown="selectEquipmentFromEl(this)">' +
           '<div class="eq-code">' + codeHl + '</div>' +
           '<div class="eq-desc">' + descHl + '</div>' +
           '</div>';
  }).join('');
  dropdown.style.display = 'block';
}

/**
 * อ่านค่าจาก data attribute แล้วส่งไปกรอกฟอร์ม
 */
function selectEquipmentFromEl(el) {
  var isInactive = el.getAttribute('data-inactive') === 'true';
  var gseNo = el.getAttribute('data-gse');
  var desc  = el.getAttribute('data-desc');
  var warnEl = document.getElementById('equipmentInactiveWarning');
  var codeInput = document.getElementById('fEquipmentCode');

  if (isInactive) {
    showToast('อุปกรณ์ ' + gseNo + ' มีสถานะ Inactive ไม่สามารถแจ้งซ่อมได้', 'error');
    if (warnEl) {
      warnEl.innerHTML = '<i class="fas fa-ban"></i> รหัสอุปกรณ์ <strong>' + escapeHtml(gseNo) + '</strong> มีสถานะ Inactive ไม่สามารถแจ้งซ่อมได้';
      warnEl.style.display = 'flex';
    }
    if (codeInput) {
      codeInput.value = gseNo;
      codeInput.focus();
    }
    document.getElementById('equipmentDropdown').style.display = 'none';
    return;
  }

  if (warnEl) warnEl.style.display = 'none';
  selectEquipment(gseNo, desc);
}

/**
 * highlight คำที่ค้นหาใน string
 */
function highlightMatch(str, query) {
  const idx = str.toUpperCase().indexOf(query);
  if (idx === -1) return str;
  return str.substring(0, idx) +
         '<mark style="background:#fff176;padding:0;">' + str.substring(idx, idx + query.length) + '</mark>' +
         str.substring(idx + query.length);
}

/**
 * เมื่อ user เลือกอุปกรณ์จาก dropdown
 */
function selectEquipment(gseNo, description) {
  const codeInput = document.getElementById('fEquipmentCode');
  const nameInput = document.getElementById('fEquipmentName');
  if (codeInput) {
    codeInput.value = gseNo;
    codeInput.style.borderColor = '';
    codeInput.style.boxShadow = '';
  }
  if (nameInput) nameInput.value = description;
  document.getElementById('equipmentDropdown').style.display = 'none';
  const warnEl = document.getElementById('equipmentInactiveWarning');
  if (warnEl) warnEl.style.display = 'none';
}

/**
 * ซ่อน dropdown เมื่อ blur และตรวจสอบว่ารหัสอุปกรณ์มีใน sheet GSE MASTER หรือไม่
 */
function onEquipmentCodeBlur() {
  setTimeout(function() {
    const dropdown = document.getElementById('equipmentDropdown');
    if (dropdown) dropdown.style.display = 'none';

    const codeInput = document.getElementById('fEquipmentCode');
    const nameInput = document.getElementById('fEquipmentName');
    const warnEl = document.getElementById('equipmentInactiveWarning');
    const code = codeInput ? codeInput.value.trim() : '';

    if (!code) {
      if (nameInput) nameInput.value = '';
      if (warnEl) warnEl.style.display = 'none';
      if (codeInput) {
        codeInput.style.borderColor = '';
        codeInput.style.boxShadow = '';
      }
      return;
    }

    if (equipmentMasterList === null || equipmentMasterList.length === 0) {
      loadEquipmentMaster(function() {
        onEquipmentCodeBlur();
      });
      return;
    }

    const match = findEquipmentInMaster(code);
    if (match) {
      // มีในระบบ GSE MASTER
      codeInput.value = match.gseNo;
      if (nameInput) nameInput.value = match.description || '';
      codeInput.style.borderColor = '';
      codeInput.style.boxShadow = '';

      const isInactive = isEquipmentInactive(match.gseNo) || match.isInactive;
      if (isInactive) {
        if (warnEl) {
          warnEl.innerHTML = '<i class="fas fa-ban"></i> รหัสอุปกรณ์ <strong>' + escapeHtml(match.gseNo) + '</strong> มีสถานะ Inactive ไม่สามารถแจ้งซ่อมได้';
          warnEl.style.display = 'flex';
        }
      } else {
        if (warnEl) warnEl.style.display = 'none';
      }
    } else {
      // ไม่มีในระบบ GSE MASTER
      if (nameInput) nameInput.value = '';
      if (codeInput) {
        codeInput.style.borderColor = '#EF4444';
        codeInput.style.boxShadow = '0 0 0 3px rgba(239, 68, 68, 0.15)';
      }
      if (warnEl) {
        warnEl.innerHTML = '<i class="fas fa-exclamation-triangle"></i> รหัสอุปกรณ์ <strong>' + escapeHtml(code) + '</strong> ไม่มีในระบบ ไม่สามารถแจ้งซ่อมอุปกรณ์ดังกล่าวได้';
        warnEl.style.display = 'flex';
      }
      showToast('ไม่มีในระบบ ไม่สามารถแจ้งซ่อมอุปกรณ์ดังกล่าวได้', 'error');
    }
  }, 200);
}

