function closeDuplicateModal() {
  _pendingSaveData = null;
  document.getElementById('duplicateModal').style.display = 'none';
}

/**
 * เมื่อ user กด "ยืนยัน แจ้งซ่อมเพิ่มเติม" ใน duplicate modal
 */
function confirmSaveDespiteDuplicate() {
  document.getElementById('duplicateModal').style.display = 'none';
  if (_pendingSaveData) {
    doSaveRequest(_pendingSaveData.data, _pendingSaveData.mode, _pendingSaveData.uuid);
    _pendingSaveData = null;
  }
}

/**
 * แสดง duplicate warning modal
 */
function showDuplicateModal(equipmentCode, existingRequests, data, mode, uuid) {
  document.getElementById('dupEquipCode').textContent = equipmentCode;
  const listEl = document.getElementById('dupRequestList');
  listEl.innerHTML = existingRequests.map(function(r) {
    return '<div class="dup-request-item">' +
           '<span class="dup-rid">ใบที่ ' + (r.requestId || '-') + '</span>' +
           '<span class="dup-status">' + (r.status || '') + '</span>' +
           '<div style="margin-top:4px;color:#555;">' +
           '📅 ' + (r.informDate || '-') + '  |  อาการ: ' + (r.damageAppearance || '-').substring(0, 60) + (r.damageAppearance && r.damageAppearance.length > 60 ? '...' : '') +
           '</div></div>';
  }).join('');
  _pendingSaveData = { data: data, mode: mode, uuid: uuid };
  document.getElementById('duplicateModal').style.display = 'flex';
}

// ============================================================
// === TECHNICIAN REPORT & SPARE PARTS ===
// ============================================================
let techniciansListCache = null;

/**
 * โหลดรายชื่อช่างทั้ง 25 ท่านสำหรับ Dropdown Action By
 */
function loadTechniciansList(callback) {
  if (techniciansListCache !== null) {
    if (callback) callback(techniciansListCache);
    return;
  }
  google.script.run
    .withSuccessHandler(function(list) {
      techniciansListCache = list || [];
      if (callback) callback(techniciansListCache);
    })
    .withFailureHandler(function(err) {
      console.error('Error loading technicians list:', err);
      techniciansListCache = [];
      if (callback) callback([]);
    })
    .getTechniciansList();
}

/**
 * เปิดหน้าบันทึกผลการซ่อมบำรุงสำหรับช่าง
 */
function showTechnicianForm(uuid) {
  showLoading();
  google.script.run
    .withSuccessHandler(function(request) {
      hideLoading();
      if (!request) {
        showToast('ไม่พบข้อมูลใบแจ้งซ่อม', 'error');
        return;
      }

      document.getElementById('techFormUUID').value = uuid;
      document.getElementById('techFormTitle').textContent = 'บันทึกผลการซ่อมบำรุง: ' + (request.RequestID || request.WorkOrderNo || '');

      // เติมข้อมูลเดิม (อ่านอย่างเดียว)
      setText('tViewRequestId', request.RequestID || '-');
      setText('tViewWorkOrderNo', request.WorkOrderNo || '-');
      setText('tViewEquipmentCode', request.EquipmentCode || '-');
      setText('tViewEquipmentName', request.EquipmentName || '-');
      setText('tViewInformDateTime', (request.InformDate || '-') + ' ' + (cleanDisplayTime(request.InformTime) || ''));
      setText('tViewHrKm', request.HrKm || '-');
      setText('tViewDamageAppearance', request.DamageAppearance || '-');
      setText('tViewRequester', (request.RequesterName || '-') + (request.RequesterID ? ' (' + request.RequesterID + ')' : ''));
      setText('tViewReceiver', (request.ReceivedBy || '-') + (request.ReceivedDate ? ' (' + request.ReceivedDate + ' ' + cleanDisplayTime(request.ReceivedTime) + ')' : ''));
      setText('tViewEstimateDateTime', (formatDateDMY(request.EstimateDate) || '-') + (request.EstimateTime ? ' ' + cleanDisplayTime(request.EstimateTime) : ''));

      // แสดง Alert เมื่อเป็นงานที่ถูกส่งกลับแก้ไข (Rework)
      const reworkAlert = document.getElementById('techReworkAlert');
      const reworkText = document.getElementById('techReworkReasonText');
      if (reworkAlert && reworkText) {
        if (request.ReworkReason && request.ReworkReason.trim()) {
          reworkText.textContent = request.ReworkReason;
          reworkAlert.style.display = 'block';
        } else {
          reworkAlert.style.display = 'none';
        }
      }

      // โหลดรายชื่อช่างสำหรับ dropdown Action By 1, 2 และ 3
      loadTechniciansList(function(techs) {
        const defaultActionBy1 = request.ActionBy1 || currentUser.employeeId || '';
        populateTechDropdown('tActionBy1', techs, defaultActionBy1, '-- เลือกช่างผู้รับผิดชอบหลัก --');
        populateTechDropdown('tActionBy2', techs, request.ActionBy2 || '', '-- ไม่มี / เลือกช่าง --');
        populateTechDropdown('tActionBy3', techs, request.ActionBy3 || '', '-- ไม่มี / เลือกช่าง --');
        refreshTechDropdowns();
      });

      // รายละเอียดการซ่อมบำรุง (ข้อ 2.1)
      document.getElementById('tMaintenanceDetails').value = request.MaintenanceDetails || '';

      // กำหนดวันเสร็จ และ เวลากำหนดเสร็จ
      if (document.getElementById('tEstimateDate')) {
        document.getElementById('tEstimateDate').value = parseDateToInput(request.EstimateDate) || '';
      }
      if (document.getElementById('tEstimateTime')) {
        document.getElementById('tEstimateTime').value = parseTimeToInput(request.EstimateTime) || '';
      }

      // วันเสร็จ / เวลาเสร็จ / เวลาที่ใช้จริง
      const today = new Date();
      document.getElementById('tCompleteDate').value = parseDateToInput(request.CompleteDate) || formatDateForInput(today);
      document.getElementById('tCompleteTime').value = parseTimeToInput(request.CompleteTime) || formatTimeForInput(today);
      document.getElementById('tActualRepairTime').value = request.ActualRepairTime || '';

      // เคลียร์และเติมรายการอะไหล่เดิม
      const tbody = document.getElementById('sparePartsTbody');
      tbody.innerHTML = '';
      const existingParts = request.spareParts || [];
      if (existingParts.length > 0) {
        existingParts.forEach(function(p) {
          addSparePartRow(p);
        });
      } else {
        // แถวว่างเริ่มต้น 1 แถว
        addSparePartRow();
      }

      showPage('techReportPage');
    })
    .withFailureHandler(function(error) {
      hideLoading();
      showToast('ไม่สามารถโหลดข้อมูลได้: ' + error.message, 'error');
    })
    .getRequestByUUID(uuid);
}

function populateTechDropdown(selectId, techs, selectedValue, defaultLabel) {
  const sel = document.getElementById(selectId);
  if (!sel) return;
  const label = defaultLabel || (selectId === 'tActionBy1' ? '-- เลือกช่างผู้รับผิดชอบหลัก --' : '-- ไม่มี / เลือกช่าง --');
  let html = '<option value="">' + escapeHtml(label) + '</option>';
  let found = false;
  (techs || []).forEach(function(t) {
    const isSel = (selectedValue && (selectedValue === t.employeeId || selectedValue === t.fullName)) ? 'selected' : '';
    if (isSel) found = true;
    html += '<option value="' + escapeAttr(t.employeeId) + '" ' + isSel + '>' +
            escapeHtml(t.employeeId + ' - ' + t.fullName) + '</option>';
  });
  if (selectedValue && !found) {
    html += '<option value="' + escapeAttr(selectedValue) + '" selected>' + escapeHtml(selectedValue) + '</option>';
  }
  sel.innerHTML = html;
}

/**
 * ตรวจจับการเปลี่ยนตัวเลือกช่าง และป้องกันไม่ให้เลือกช่างคนเดียวกันซ้ำข้ามช่อง
 */
function onTechSelectChange(changedSelectId) {
  const s1 = document.getElementById('tActionBy1');
  const s2 = document.getElementById('tActionBy2');
  const s3 = document.getElementById('tActionBy3');
  if (!s1 || !s2 || !s3) return;

  const val1 = s1.value.trim();
  const val2 = s2.value.trim();
  const val3 = s3.value.trim();

  const changedEl = document.getElementById(changedSelectId);
  const changedVal = changedEl ? changedEl.value.trim() : '';

  if (changedVal) {
    let duplicate = false;
    if (changedSelectId === 'tActionBy1' && (changedVal === val2 || changedVal === val3)) duplicate = true;
    if (changedSelectId === 'tActionBy2' && (changedVal === val1 || changedVal === val3)) duplicate = true;
    if (changedSelectId === 'tActionBy3' && (changedVal === val1 || changedVal === val2)) duplicate = true;

    if (duplicate) {
      showToast('รหัสพนักงานช่างนี้ถูกเลือกในช่องอื่นแล้ว ไม่สามารถเลือกซ้ำได้', 'warning');
      changedEl.value = '';
    }
  }

  refreshTechDropdowns();
}

/**
 * ปิดการเลือก (disable) รายชื่อช่างที่ถูกเลือกไปแล้วในช่องอื่น
 */
function refreshTechDropdowns() {
  const ids = ['tActionBy1', 'tActionBy2', 'tActionBy3'];
  const selects = ids.map(function(id) { return document.getElementById(id); });
  if (selects.some(function(s) { return !s; })) return;

  const values = selects.map(function(s) { return s.value.trim(); });

  selects.forEach(function(sel, index) {
    const otherValues = values.filter(function(v, i) { return i !== index && v !== ''; });
    Array.from(sel.options).forEach(function(opt) {
      if (!opt.value) {
        opt.disabled = false;
      } else {
        opt.disabled = otherValues.includes(opt.value);
      }
    });
  });
}

function addSparePartRow(data) {
  const tbody = document.getElementById('sparePartsTbody');
  if (tbody.children.length >= 4) {
    showToast('สามารถเพิ่มรายการอะไหล่ได้สูงสุด 4 รายการตามขนาดฟอร์มเอกสาร', 'warning');
    return;
  }

  const rowIdx = tbody.children.length + 1;
  const p = data || {};
  const tr = document.createElement('tr');
  tr.innerHTML =
    '<td class="sp-col-header-mobile">' +
      '<div class="sp-card-header">' +
        '<span class="sp-badge-num"><i class="fas fa-cube"></i> อะไหล่รายการที่ <span class="sp-row-num">' + rowIdx + '</span></span>' +
        '<button type="button" class="btn-delete-row-mobile" title="ลบรายการนี้" onclick="deleteSparePartRow(this)"><i class="fas fa-trash-alt"></i> ลบรายการ</button>' +
      '</div>' +
    '</td>' +
    '<td class="sp-col-idx desktop-only" style="text-align:center;font-weight:600;color:#64748B;"><span class="sp-row-num-dt">' + rowIdx + '</span></td>' +
    '<td class="sp-col-name">' +
      '<label class="sp-label-mobile">ชื่อชิ้นส่วนอะไหล่ที่เปลี่ยน (Spare Part Replace)</label>' +
      '<input type="text" class="sp-name" placeholder="ระบุชื่อชิ้นส่วนอะไหล่..." value="' + escapeAttr(p.sparePartName) + '">' +
    '</td>' +
    '<td class="sp-col-no">' +
      '<label class="sp-label-mobile">Part No.</label>' +
      '<input type="text" class="sp-no" placeholder="Part No." value="' + escapeAttr(p.partNo) + '">' +
    '</td>' +
    '<td class="sp-col-type">' +
      '<label class="sp-label-mobile">ชนิด/รุ่น (Type/Model)</label>' +
      '<input type="text" class="sp-type" placeholder="ชนิด/รุ่น" value="' + escapeAttr(p.typeModel) + '">' +
    '</td>' +
    '<td class="sp-col-qty">' +
      '<label class="sp-label-mobile">จำนวน (QTY)</label>' +
      '<input type="text" class="sp-qty" placeholder="จำนวน" value="' + escapeAttr(p.qty) + '" style="text-align:center;">' +
    '</td>' +
    '<td class="sp-col-price">' +
      '<label class="sp-label-mobile">ราคา (Price)</label>' +
      '<input type="text" class="sp-price" placeholder="ราคา" value="' + escapeAttr(p.price) + '" style="text-align:right;">' +
    '</td>' +
    '<td class="sp-col-del desktop-only" style="text-align:center;">' +
      '<button type="button" class="btn-delete-row" title="ลบรายการ" onclick="deleteSparePartRow(this)"><i class="fas fa-trash"></i></button>' +
    '</td>';

  tbody.appendChild(tr);
  updateSparePartsRowNumbers();
}

function deleteSparePartRow(btn) {
  const row = btn.closest('tr');
  if (row) {
    row.remove();
    updateSparePartsRowNumbers();
  }
}

function updateSparePartsRowNumbers() {
  const rows = document.querySelectorAll('#sparePartsTbody tr');
  rows.forEach(function(tr, idx) {
    const mobileNum = tr.querySelector('.sp-row-num');
    if (mobileNum) mobileNum.textContent = idx + 1;
    const dtNum = tr.querySelector('.sp-row-num-dt');
    if (dtNum) dtNum.textContent = idx + 1;
  });
}

function handleSaveTechnicianReport() {
  const uuid = document.getElementById('techFormUUID').value;
  if (!uuid) {
    showToast('ไม่พบรหัสใบแจ้งซ่อม', 'error');
    return;
  }

  const maintenanceDetails = document.getElementById('tMaintenanceDetails').value.trim();
  const actualRepairTime = document.getElementById('tActualRepairTime').value.trim();
  const completeDate = document.getElementById('tCompleteDate').value;
  const completeTime = document.getElementById('tCompleteTime').value;
  const actionBy1 = document.getElementById('tActionBy1') ? document.getElementById('tActionBy1').value.trim() : '';
  const actionBy2 = document.getElementById('tActionBy2') ? document.getElementById('tActionBy2').value.trim() : '';
  const actionBy3 = document.getElementById('tActionBy3') ? document.getElementById('tActionBy3').value.trim() : '';

  if (!actionBy1) {
    showToast('กรุณาเลือกช่างผู้รับผิดชอบหลัก (คนที่ 1)', 'error');
    if (document.getElementById('tActionBy1')) document.getElementById('tActionBy1').focus();
    return;
  }

  // ป้องกันการเลือกช่างซ้ำกัน
  const selectedTechs = [actionBy1, actionBy2, actionBy3].filter(Boolean);
  const uniqueTechs = new Set(selectedTechs);
  if (uniqueTechs.size !== selectedTechs.length) {
    showToast('ไม่สามารถเลือกช่างผู้ปฏิบัติงานซ้ำกันได้ กรุณาตรวจสอบรายชื่อช่างคนที่ 1, 2 และ 3', 'error');
    return;
  }

  if (!maintenanceDetails) {
    showToast('กรุณาระบุรายละเอียดในการซ่อมบำรุง (ข้อ 2.1)', 'error');
    document.getElementById('tMaintenanceDetails').focus();
    return;
  }

  if (!actualRepairTime) {
    showToast('กรุณาระบุเวลาที่ใช้ซ่อมจริง (เช่น 2 ชม.)', 'error');
    document.getElementById('tActualRepairTime').focus();
    return;
  }

  if (!completeDate || !completeTime) {
    showToast('กรุณาระบุวันและเวลาที่แล้วเสร็จ', 'error');
    return;
  }

  // รวบรวมข้อมูลอะไหล่
  const rows = document.querySelectorAll('#sparePartsTbody tr');
  const spareParts = [];
  rows.forEach(function(tr) {
    const name = tr.querySelector('.sp-name').value.trim();
    const partNo = tr.querySelector('.sp-no').value.trim();
    const typeModel = tr.querySelector('.sp-type').value.trim();
    const qty = tr.querySelector('.sp-qty').value.trim();
    const price = tr.querySelector('.sp-price').value.trim();
    if (name || partNo || typeModel || qty || price) {
      spareParts.push({
        sparePartName: name,
        partNo: partNo,
        typeModel: typeModel,
        qty: qty,
        price: price
      });
    }
  });

  // กำหนดชื่อผู้ซ่อม/ผู้บันทึกผล (technicianName) ให้ตรงกับช่างหลักคนที่ 1 เสมอ
  let leadTechName = '';
  if (techniciansListCache && techniciansListCache.length > 0) {
    const matchedTech = techniciansListCache.find(function(t) { return t.employeeId === actionBy1; });
    if (matchedTech) leadTechName = matchedTech.fullName;
  }
  if (!leadTechName && currentUser && currentUser.employeeId === actionBy1) {
    leadTechName = currentUser.fullName;
  }
  if (!leadTechName) {
    leadTechName = actionBy1;
  }

  const techData = {
    maintenanceDetails: maintenanceDetails,
    actualRepairTime: actualRepairTime,
    completeDate: completeDate,
    completeTime: completeTime,
    actionBy1: actionBy1,
    actionBy2: actionBy2,
    actionBy3: actionBy3,
    technicianName: leadTechName,
    technicianEmpId: actionBy1,
    estimateDate: formatDateDMY(document.getElementById('tEstimateDate') ? document.getElementById('tEstimateDate').value : ''),
    estimateTime: document.getElementById('tEstimateTime') ? document.getElementById('tEstimateTime').value : '',
    spareParts: spareParts
  };

  showLoading();
  google.script.run
    .withSuccessHandler(function(result) {
      hideLoading();
      if (result.success) {
        showToast(result.message, 'success');
        showPage('dashboardPage');
        loadDashboardData(true);
      } else {
        showToast(result.message, 'error');
      }
    })
    .withFailureHandler(function(err) {
      hideLoading();
      showToast('เกิดข้อผิดพลาด: ' + err.message, 'error');
    })
    .saveTechnicianReport(uuid, techData);
}

