let currentEndorsementRequest = null;
let isReworkMode = false;

function showEndorsementModal(uuid) {
  showLoading();
  google.script.run
    .withSuccessHandler(function(request) {
      hideLoading();
      if (!request) {
        showToast('ไม่พบข้อมูลใบแจ้งซ่อม', 'error');
        return;
      }
      currentEndorsementRequest = request;
      isReworkMode = false;

      // 1. เติมข้อมูลอุปกรณ์และใบสั่งงาน
      setText('endEqCode', request.EquipmentCode || '-');
      setText('endEqName', request.EquipmentName || '-');
      setText('endReqId', request.RequestID || '-');
      setText('endWoNo', request.WorkOrderNo || '-');
      setText('endInformDate', request.InformDate || '-');
      setText('endRequester', (request.RequesterName || '') + (request.RequesterID ? ' (' + request.RequesterID + ')' : ''));
      setText('endDamage', request.DamageAppearance || '-');

      // 2. เติมข้อมูลสรุปผลการซ่อม
      setText('endMaintenanceDetails', request.MaintenanceDetails || '(ยังไม่มีรายละเอียด)');
      setText('endActionBy1', request.ActionBy1 || '-');
      setText('endActionBy2', request.ActionBy2 || '-');
      setText('endActionBy3', request.ActionBy3 || '-');
      setText('endRepairTime', request.ActualRepairTime || '-');
      setText('endTechName', request.TechnicianName || '-');
      const compDate = formatDateDMY(request.CompleteDate);
      const compTime = cleanDisplayTime(request.CompleteTime);
      setText('endCompleteDateTime', (compDate || '-') + (compTime ? ' ' + compTime : ''));

      // เติมตารางอะไหล่
      const partsTbody = document.getElementById('endPartsTableBody');
      const parts = request.spareParts || [];
      if (parts.length === 0) {
        partsTbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:10px; color:#94A3B8;">ไม่มีรายการอะไหล่ที่เปลี่ยน</td></tr>';
      } else {
        let phtml = '';
        parts.forEach(function(p, idx) {
          phtml += '<tr>';
          phtml += '<td style="text-align:center; color:#64748B;">' + (idx + 1) + '</td>';
          phtml += '<td>' + escapeHtml(p.sparePartName || '-') + '</td>';
          phtml += '<td>' + escapeHtml(p.partNo || '-') + '</td>';
          phtml += '<td>' + escapeHtml(p.typeModel || '-') + '</td>';
          phtml += '<td style="text-align:center;">' + escapeHtml(p.qty || '-') + '</td>';
          phtml += '</tr>';
        });
        partsTbody.innerHTML = phtml;
      }

      // แสดง Alert เมื่อเคยถูกส่งกลับแก้ไข
      const reworkBox = document.getElementById('endReworkNoticeBox');
      const reworkText = document.getElementById('endReworkNoticeText');
      if (request.ReworkReason && request.ReworkReason.trim()) {
        reworkText.textContent = request.ReworkReason;
        reworkBox.style.display = 'block';
      } else {
        reworkBox.style.display = 'none';
      }

      // 3. ประวัติการอนุมัติที่ผ่านมา
      const prevBox = document.getElementById('endPreviousApprovals');
      const supHist = document.getElementById('endSupervisorHistory');
      const mgrHist = document.getElementById('endManagerHistory');
      let hasHistory = false;

      if (request.SupervisorName) {
        supHist.style.display = 'block';
        setText('endSupervisorInfo', request.SupervisorName + (request.SupervisorId ? ' (' + request.SupervisorId + ')' : '') +
          ' - ' + formatDateDMY(request.SupervisorDate) + (request.SupervisorTime ? ' ' + cleanDisplayTime(request.SupervisorTime) : ''));
        setText('endSupervisorNotes', request.SupervisorNotes ? 'ความเห็น: ' + request.SupervisorNotes : '');
        hasHistory = true;
      } else {
        supHist.style.display = 'none';
      }

      if (request.ManagerName) {
        mgrHist.style.display = 'block';
        setText('endManagerInfo', request.ManagerName + (request.ManagerId ? ' (' + request.ManagerId + ')' : '') +
          ' - ' + formatDateDMY(request.ManagerDate) + (request.ManagerTime ? ' ' + cleanDisplayTime(request.ManagerTime) : ''));
        setText('endManagerNotes', request.ManagerNotes ? 'ความเห็น: ' + request.ManagerNotes : '');
        hasHistory = true;
      } else {
        mgrHist.style.display = 'none';
      }
      prevBox.style.display = hasHistory ? 'block' : 'none';

      // 4. สิทธิ์และการกระทำ (Action Box)
      const userRole = (currentUser ? (currentUser.role || 'user') : 'user').toLowerCase();
      const userEmpId = (currentUser ? (currentUser.employeeId || '') : '').toUpperCase();
      const reqEmpId = (request.RequesterID || '').toString().trim().toUpperCase();
      const isOwner = reqEmpId === userEmpId;
      const isAdmin = userRole === 'admin';
      const isSup = userRole === 'supervisor';
      const isMgr = userRole === 'manager';
      const st = (request.Status || 'รอดำเนินการ').toString().trim();

      // Reset form controls
      document.getElementById('endNotes').value = '';
      document.getElementById('endReworkReason').value = '';
      document.getElementById('endReworkGroup').style.display = 'none';
      document.getElementById('btnEndRework').style.display = 'none';
      document.getElementById('btnEndApprove').style.display = 'none';
      document.getElementById('btnEndAccept').style.display = 'none';
      document.getElementById('btnEndCloseWo').style.display = 'none';
      document.getElementById('endNotesGroup').style.display = 'none';
      document.getElementById('endRequesterNotice').style.display = 'none';
      document.getElementById('endReadOnlyNotice').style.display = 'none';

      const titleEl = document.getElementById('endorsementModalTitle');
      const subTitleEl = document.getElementById('endorsementModalSubtitle');
      const iconEl = document.getElementById('endorsementModalIcon');
      const actionTitleEl = document.getElementById('endActionTitle');
      const actionIconEl = document.getElementById('endActionIcon');

      // Supervisor check step
      if ((isSup || isAdmin) && st === 'รอ Supervisor ตรวจสอบ') {
        titleEl.textContent = 'ตรวจสอบงานซ่อมบำรุง (Supervisor)';
        subTitleEl.textContent = 'ตรวจสอบความถูกต้องของงานซ่อมและอะไหล่ ก่อนส่งต่อให้ผู้จัดการอนุมัติ';
        iconEl.className = 'fas fa-clipboard-check';
        iconEl.style.color = '#0D9488';
        actionTitleEl.textContent = 'การพิจารณาของหัวหน้างาน (Supervisor Review)';
        actionIconEl.className = 'fas fa-user-check';

        document.getElementById('endNotesGroup').style.display = 'block';
        document.getElementById('endNotesLabel').textContent = 'ข้อเสนอแนะ Supervisor (ถ้ามี):';
        document.getElementById('btnEndRework').style.display = 'inline-block';
        document.getElementById('btnEndReworkText').textContent = 'ส่งกลับให้ช่างแก้ไข';
        document.getElementById('btnEndApprove').style.display = 'inline-block';
        document.getElementById('btnEndApproveText').textContent = 'ยืนยันผ่านการตรวจสอบ (ส่งต่อ Manager)';
        if (isAdmin) document.getElementById('btnEndCloseWo').style.display = 'inline-block';
      }
      // Manager approve step
      else if ((isMgr || isAdmin) && st === 'รอ Manager อนุมัติ') {
        titleEl.textContent = 'อนุมัติงานซ่อมบำรุง (Manager Approval)';
        subTitleEl.textContent = 'อนุมัติความเรียบร้อยของใบสั่งงานเพื่อส่งมอบอุปกรณ์กลับสู่การใช้งาน';
        iconEl.className = 'fas fa-stamp';
        iconEl.style.color = '#8B5CF6';
        actionTitleEl.textContent = 'การพิจารณาของผู้จัดการ (Manager Approval)';
        actionIconEl.className = 'fas fa-check-double';

        document.getElementById('endNotesGroup').style.display = 'block';
        document.getElementById('endNotesLabel').textContent = 'ข้อเสนอแนะ Manager (ถ้ามี):';
        document.getElementById('btnEndRework').style.display = 'inline-block';
        document.getElementById('btnEndReworkText').textContent = 'ส่งกลับให้ช่างแก้ไข';
        document.getElementById('btnEndApprove').style.display = 'inline-block';
        document.getElementById('btnEndApproveText').textContent = 'อนุมัติงานซ่อม (Approve)';
        if (isAdmin) document.getElementById('btnEndCloseWo').style.display = 'inline-block';
      }
      // Accept equipment step (เปิดให้ผู้ใช้ทุกคนสามารถรับมอบอุปกรณ์แทนได้)
      else if (st === 'รอผู้รับอุปกรณ์ลงนาม') {
        titleEl.textContent = 'ลงนามรับมอบอุปกรณ์ (Return to Service)';
        subTitleEl.textContent = 'ผู้รับมอบอุปกรณ์ตรวจสอบความพร้อมของอุปกรณ์ก่อนลงนามรับมอบ';
        iconEl.className = 'fas fa-handshake';
        iconEl.style.color = '#2563EB';
        actionTitleEl.textContent = 'การรับมอบอุปกรณ์ (Equipment Acceptance)';
        actionIconEl.className = 'fas fa-box-open';

        document.getElementById('endRequesterNotice').style.display = 'block';
        document.getElementById('btnEndAccept').style.display = 'inline-block';
        if (isAdmin) document.getElementById('btnEndCloseWo').style.display = 'inline-block';
      }
      // Read-only inspection mode
      else {
        titleEl.textContent = 'รายละเอียดงานซ่อมและสถานะเอกสาร';
        subTitleEl.textContent = 'ดูข้อมูลสรุปผลการซ่อมและประวัติการตรวจสอบ';
        iconEl.className = 'fas fa-info-circle';
        iconEl.style.color = '#3B82F6';
        actionTitleEl.textContent = 'สถานะของใบงาน';
        actionIconEl.className = 'fas fa-info';

        document.getElementById('endReadOnlyNotice').style.display = 'block';
        const stBadge = document.getElementById('endCurrentStatusBadge');
        stBadge.className = 'status-badge ' + getStatusClass(st);
        stBadge.textContent = st;

        if (isAdmin) document.getElementById('btnEndCloseWo').style.display = 'inline-block';
      }

      // ตั้งค่าปุ่ม ปิด W/O ใน Sheet สำหรับ Admin
      if (isAdmin && (st === 'รอ Manager อนุมัติ' || st === 'รอผู้รับอุปกรณ์ลงนาม' || st === 'เสร็จสิ้น' || st === 'เสร็จสิ้น (Return to Service)')) {
        const btnCloseWo = document.getElementById('btnEndCloseWo');
        if (btnCloseWo) {
          btnCloseWo.style.display = 'inline-block';
          if (request.WoSheetStatus === 'CLOSED') {
            btnCloseWo.innerHTML = '<i class="fas fa-check-circle"></i> W/O ใน Sheet ปิดแล้ว';
            btnCloseWo.disabled = true;
            btnCloseWo.className = 'btn btn-wo-closed';
          } else {
            btnCloseWo.innerHTML = '<i class="fas fa-folder-minus"></i> ปิด W/O ใน Sheet ทันที';
            btnCloseWo.disabled = false;
            btnCloseWo.className = 'btn btn-close-wo';
          }
        }
      }

      document.getElementById('endorsementModal').style.display = 'flex';
    })
    .withFailureHandler(function(err) {
      hideLoading();
      showToast('ไม่สามารถโหลดข้อมูลได้: ' + err.message, 'error');
    })
    .getRequestByUUID(uuid);
}

