function toggleReworkInput() {
  const reworkGroup = document.getElementById('endReworkGroup');
  const reworkInput = document.getElementById('endReworkReason');
  if (reworkGroup.style.display === 'none') {
    reworkGroup.style.display = 'block';
    reworkInput.focus();
    isReworkMode = true;
    showToast('กรุณาระบุเหตุผลที่ส่งกลับแก้ไข แล้วกดยืนยันส่งกลับอีกครั้ง', 'warning');
  } else {
    handleEndorsementRework();
  }
}

function handleEndorsementRework() {
  if (!currentEndorsementRequest) return;
  const reason = document.getElementById('endReworkReason').value.trim();
  if (!reason) {
    showToast('กรุณาระบุเหตุผลที่ส่งกลับให้ช่างแก้ไข', 'error');
    document.getElementById('endReworkReason').focus();
    return;
  }

  const uuid = currentEndorsementRequest.UUID;
  const userRole = (currentUser.role || 'user').toLowerCase();
  const st = (currentEndorsementRequest.Status || '').toString().trim();

  showLoading();
  const callback = function(result) {
    hideLoading();
    if (result.success) {
      showToast(result.message, 'success');
      closeEndorsementModal();
      loadDashboardData(true);
    } else {
      showToast(result.message, 'error');
    }
  };

  if (st === 'รอ Supervisor ตรวจสอบ' || userRole === 'supervisor') {
    google.script.run
      .withSuccessHandler(callback)
      .withFailureHandler(function(e) { hideLoading(); showToast('เกิดข้อผิดพลาด: ' + e.message, 'error'); })
      .supervisorReject(uuid, currentUser.employeeId, reason);
  } else {
    google.script.run
      .withSuccessHandler(callback)
      .withFailureHandler(function(e) { hideLoading(); showToast('เกิดข้อผิดพลาด: ' + e.message, 'error'); })
      .managerReject(uuid, currentUser.employeeId, reason);
  }
}

