// ============================================================
// REAL-TIME ACTIVE USERS & GA4 MONITOR LOGIC
// ============================================================

let heartbeatInterval = null;
let latestActiveUsersData = null;

function startHeartbeat() {
  if (heartbeatInterval) clearInterval(heartbeatInterval);
  sendUserHeartbeat(); // ส่งทันทีครั้งแรก
  heartbeatInterval = setInterval(sendUserHeartbeat, 45000); // ส่งซ้ำทุกๆ 45 วินาที
}

function stopHeartbeat() {
  if (heartbeatInterval) {
    clearInterval(heartbeatInterval);
    heartbeatInterval = null;
  }
}

function sendUserHeartbeat() {
  if (!currentUser || !currentUser.employeeId) return;

  const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) || window.innerWidth <= 768;
  const payload = {
    employeeId: currentUser.employeeId,
    fullName: currentUser.fullName || '',
    role: (currentUser.role || 'user').toLowerCase(),
    deviceType: isMobile ? 'Mobile' : 'Desktop',
    currentTab: (typeof currentDashboardTab !== 'undefined' ? currentDashboardTab : 'requests')
  };

  google.script.run
    .withSuccessHandler(function(res) {
      if (res && res.success) {
        updateActiveUsersUI(res);
      }
    })
    .withFailureHandler(function(err) {
      console.warn('Heartbeat ping failed:', err);
    })
    .recordUserHeartbeat(payload);
}

function updateActiveUsersUI(res) {
  if (!res) return;
  const count = res.activeCount || 1;
  const navCountEl = document.getElementById('navActiveUsersCount');
  if (navCountEl) {
    navCountEl.textContent = count + ' ออนไลน์';
  }
  const tbCountEl = document.getElementById('toolbarActiveCount');
  if (tbCountEl) {
    tbCountEl.textContent = 'ออนไลน์ ' + count + ' คน';
  }

  if (res.activeUsers) {
    latestActiveUsersData = res.activeUsers;
    const modal = document.getElementById('activeUsersModal');
    if (modal && modal.style.display !== 'none') {
      renderActiveUsersModalContent(res.activeUsers, count);
    }
  }
}

function openActiveUsersModal() {
  const modal = document.getElementById('activeUsersModal');
  if (!modal) return;
  modal.style.display = 'flex';
  refreshActiveUsersModal();
}

function closeActiveUsersModal() {
  const modal = document.getElementById('activeUsersModal');
  if (modal) modal.style.display = 'none';
}

function refreshActiveUsersModal() {
  const icon = document.getElementById('refreshActiveIcon');
  if (icon) icon.classList.add('fa-spin');

  google.script.run
    .withSuccessHandler(function(res) {
      if (icon) icon.classList.remove('fa-spin');
      if (res && res.success) {
        latestActiveUsersData = res.activeUsers || [];
        renderActiveUsersModalContent(latestActiveUsersData, res.activeCount || 1);
        if (res.gaMeasurementId) {
          const input = document.getElementById('inputGaMeasurementId');
          if (input) input.value = res.gaMeasurementId;
        }
      }
    })
    .withFailureHandler(function(err) {
      if (icon) icon.classList.remove('fa-spin');
      showToast('ไม่สามารถดึงข้อมูลผู้ใช้งานออนไลน์ได้: ' + err.message, 'error');
    })
    .getActiveUsersData();
}

function renderActiveUsersModalContent(users, totalCount) {
  const usersList = users || [];
  let mobileCount = 0;
  let desktopCount = 0;

  usersList.forEach(function(u) {
    if (u.deviceType === 'Mobile') mobileCount++;
    else desktopCount++;
  });

  const elTotal = document.getElementById('modalActiveTotal');
  if (elTotal) elTotal.textContent = totalCount || usersList.length;

  const elMobile = document.getElementById('modalActiveMobile');
  if (elMobile) elMobile.textContent = mobileCount;

  const elDesktop = document.getElementById('modalActiveDesktop');
  if (elDesktop) elDesktop.textContent = desktopCount;

  const tbody = document.getElementById('activeUsersTbody');
  if (!tbody) return;

  if (usersList.length === 0) {
    tbody.innerHTML = '<tr><td colspan="4" style="text-align:center; padding:16px; color:#94A3B8;">ไม่มีข้อมูลผู้ใช้งานที่เชื่อมต่อขณะนี้</td></tr>';
    return;
  }

  let html = '';
  const now = Date.now();
  usersList.forEach(function(u) {
    const isMe = currentUser && String(u.employeeId).toUpperCase() === String(currentUser.employeeId).toUpperCase();
    const roleUpper = (u.role || 'user').toUpperCase();
    const deviceIcon = u.deviceType === 'Mobile' ? '<i class="fas fa-mobile-alt" style="color:#2563EB;"></i> มือถือ' : '<i class="fas fa-desktop" style="color:#059669;"></i> คอมพิวเตอร์';
    const secondsAgo = Math.max(0, Math.floor((now - (u.lastPing || now)) / 1000));
    let timeAgoText = secondsAgo < 15 ? 'ใช้งานอยู่ขณะนี้' : (secondsAgo + ' วิ ที่แล้ว');

    html += '<tr style="border-bottom:1px solid #F1F5F9; ' + (isMe ? 'background:#F0FDF4;' : '') + '">';
    html += '<td style="padding:10px 12px;">' +
              '<strong>' + escapeHtml(u.fullName || u.employeeId) + '</strong>' +
              (isMe ? ' <span style="font-size:0.7rem; background:#DCFCE7; color:#15803D; padding:1px 6px; border-radius:10px; font-weight:700;">(คุณ)</span>' : '') +
              '<div style="font-size:0.75rem; color:#64748B;">รหัส: ' + escapeHtml(u.employeeId) + '</div>' +
            '</td>';
    html += '<td style="padding:10px 12px;"><span style="font-size:0.75rem; font-weight:600; background:#E2E8F0; padding:2px 8px; border-radius:10px; color:#334155;">' + escapeHtml(roleUpper) + '</span></td>';
    html += '<td style="padding:10px 12px; text-align:center; font-size:0.82rem;">' + deviceIcon + '</td>';
    html += '<td style="padding:10px 12px; text-align:right;">' +
              '<span style="display:inline-flex; align-items:center; gap:5px; font-size:0.78rem; color:#16A34A; font-weight:600;">' +
                '<span class="active-pulse-dot" style="width:6px; height:6px;"></span> ' + timeAgoText +
              '</span>' +
            '</td>';
    html += '</tr>';
  });

  tbody.innerHTML = html;
}

function handleSaveGaId() {
  const input = document.getElementById('inputGaMeasurementId');
  if (!input) return;
  const val = input.value.trim().toUpperCase();

  showLoading();
  google.script.run
    .withSuccessHandler(function(res) {
      hideLoading();
      if (res && res.success) {
        showToast(res.message, 'success');
        if (input) input.value = res.gaMeasurementId || '';
      } else {
        showToast(res ? res.message : 'เกิดข้อผิดพลาดในการบันทึก', 'error');
      }
    })
    .withFailureHandler(function(err) {
      hideLoading();
      showToast('เกิดข้อผิดพลาด: ' + err.message, 'error');
    })
    .saveGaMeasurementId(val);
}

// ============================================================
// === PREVENTIVE MAINTENANCE (PM) LOGIC & CONTROLLERS ===
// ============================================================

let currentPmStatusFilter = '';
let currentPmBatchImportData = [];
let currentActivePmRequest = null;
let currentActivePmTemplate = null;
let currentPmChecklistState = [];

function filterPmStatus(status) {
  currentPmStatusFilter = status;
  const select = document.getElementById('pmStatusFilter');
  if (select) select.value = status;
  filterPmTable();
}

function filterPmTable() {
  const searchEl = document.getElementById('pmSearchInput');
  const searchTerm = searchEl ? searchEl.value.toLowerCase().trim() : '';
  const statusEl = document.getElementById('pmStatusFilter');
  const statusFilter = statusEl ? statusEl.value : '';
  const monthEl = document.getElementById('pmMonthFilter');
  const monthFilter = monthEl ? monthEl.value : '';
  const yearEl = document.getElementById('pmYearFilter');
  const yearFilter = yearEl ? yearEl.value : '';

  let filtered = (allRequests || []).filter(function(r) {
    return isPmRequest(r);
  });

  if (statusFilter) {
    filtered = filtered.filter(function(r) {
      const st = (r.Status || 'รอดำเนินการ').toString().trim();
      if (statusFilter === 'COMPLETE') return st === 'COMPLETE';
      if (statusFilter === 'เสร็จสิ้น') return st === 'เสร็จสิ้น' || st === 'เสร็จสิ้น (Return to Service)';
      return st === statusFilter;
    });
  }

  if (monthFilter) {
    const targetMonth = parseInt(monthFilter, 10);
    filtered = filtered.filter(function(r) {
      const d = r.InformDate || r.TargetDate || '';
      if (!d) return false;
      const parts = d.toString().split(/[\/\-]/);
      if (parts.length >= 3) {
        let m = -1;
        if (parts[0].length === 4) m = parseInt(parts[1], 10); // YYYY-MM-DD
        else m = parseInt(parts[1], 10); // DD/MM/YYYY
        return m === targetMonth;
      }
      return false;
    });
  }

  if (yearFilter) {
    const targetYear = parseInt(yearFilter, 10);
    filtered = filtered.filter(function(r) {
      const d = r.InformDate || r.TargetDate || '';
      if (!d) return false;
      const parts = d.toString().split(/[\/\-]/);
      if (parts.length >= 3) {
        let y = -1;
        if (parts[0].length === 4) y = parseInt(parts[0], 10);
        else y = parseInt(parts[2], 10);
        return y === targetYear;
      }
      return false;
    });
  }

  if (searchTerm) {
    filtered = filtered.filter(function(r) {
      return (r.RequestID || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.WorkOrderNo || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.EquipmentCode || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.EquipmentName || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.DamageAppearance || '').toString().toLowerCase().indexOf(searchTerm) !== -1 ||
             (r.PmCheckLevel || '').toString().toLowerCase().indexOf(searchTerm) !== -1;
    });
  }

  renderPmTable(filtered);
}

function renderPmDashboard() {
  recomputeAndUpdateCounts();
  filterPmTable();
}

function renderPmTable(pmRequests) {
  const tbody = document.getElementById('pmTableBody');
  if (!tbody) return;

  if (!pmRequests || pmRequests.length === 0) {
    tbody.innerHTML = '<tr class="tr-empty"><td colspan="10" class="empty-message">' +
      '<i class="fas fa-calendar-check"></i><p>ไม่มีข้อมูลแผนบำรุงรักษา (PM) ตรงตามเงื่อนไข</p></td></tr>';
    return;
  }

  const userRole = (currentUser ? (currentUser.role || 'user') : 'user').toLowerCase();
  const isAdmin = userRole === 'admin';
  const isSup = userRole === 'supervisor';
  const isMgr = userRole === 'manager';

  let html = '';
  pmRequests.forEach(function(r, index) {
    const reqStatus = (r.Status || 'รอดำเนินการ').toString().trim();
    let badgeClass = 'status-pending';
    if (reqStatus === 'กำลังซ่อม') badgeClass = 'status-progress';
    else if (reqStatus === 'รอ Supervisor ตรวจสอบ') badgeClass = 'status-supervisor';
    else if (reqStatus === 'รอ Manager อนุมัติ') badgeClass = 'status-manager';
    else if (reqStatus === 'COMPLETE') badgeClass = 'status-complete';
    else if (reqStatus === 'เสร็จสิ้น' || reqStatus === 'เสร็จสิ้น (Return to Service)') badgeClass = 'status-completed';

    const checkLevelText = r.PmCheckLevel || r.DamageAppearance || 'Check A';
    const targetDateText = r.InformDate || r.TargetDate || '-';
    const techName = r.TechnicianName || r.ActionBy1 || '-';
    const woDisplay = r.WorkOrderNo ? '<span class="badge-wo">' + escapeHtml(r.WorkOrderNo) + '</span>' : '<span style="color:#94A3B8;">-</span>';

    html += '<tr>';
    html += '<td style="text-align: center; color: #94A3B8;">' + (index + 1) + '</td>';
    html += '<td style="font-weight: 700; color: #2563EB;">' + escapeHtml(r.RequestID || '') + '</td>';
    html += '<td>' + woDisplay + '</td>';
    html += '<td><span class="cell-equipment-code">' + escapeHtml(r.EquipmentCode || '') + '</span></td>';
    html += '<td>' + escapeHtml(r.EquipmentName || '') + '</td>';
    html += '<td><span class="pm-tc-badge">' + escapeHtml(checkLevelText) + '</span></td>';
    html += '<td>' + escapeHtml(targetDateText) + '</td>';
    html += '<td>' + escapeHtml(techName) + '</td>';
    html += '<td><span class="status-badge ' + badgeClass + '">' + escapeHtml(reqStatus) + '</span></td>';

    // Actions (รูปแบบเหมือน CM ทุกประการ สวยงาม กลมมน พอดีช่อง ไม่บวมซ้อน)
    const canSupervisorApprove = (isAdmin || isSup) && reqStatus === 'รอ Supervisor ตรวจสอบ';
    const canManagerApprove = (isAdmin || isMgr) && reqStatus === 'รอ Manager อนุมัติ';

    html += '<td class="col-actions"><div class="actions-cell">';

    // 1. ปุ่มพิมพ์ Task Card (เขียว เหมือน CM)
    html += '<button class="btn btn-icon btn-print" title="พิมพ์ใบ Task Card (A4)" onclick="openPmTaskCardAndPrint(\'' + r.UUID + '\')">' +
            '<i class="fas fa-print"></i></button>';

    // 2. ปุ่ม Supervisor ตรวจสอบ (เหลือง/ส้ม เหมือน CM)
    if (canSupervisorApprove) {
      html += '<button class="btn btn-icon btn-supervisor" title="ตรวจสอบงาน PM (Supervisor)" onclick="openPmTaskCard(\'' + r.UUID + '\')">' +
              '<i class="fas fa-clipboard-check"></i></button>';
    }

    // 3. ปุ่ม Manager อนุมัติ (ม่วง เหมือน CM)
    if (canManagerApprove) {
      html += '<button class="btn btn-icon btn-manager" title="อนุมัติงาน PM (Manager)" onclick="openPmTaskCard(\'' + r.UUID + '\')">' +
              '<i class="fas fa-stamp"></i></button>';
    }

    // 4. ปุ่ม Digital Task Card (ฟ้าคราม PM สดใส สวยงาม ต่างจาก CM)
    html += '<button class="btn btn-icon btn-pm-card" title="เปิดบันทึก/ดูผล Task Card" onclick="openPmTaskCard(\'' + r.UUID + '\')">' +
            '<i class="fas fa-calendar-check"></i></button>';

    // 5. ปุ่ม Admin ปิดงานในระบบและ Sheet (เมื่อ COMPLETE)
    if (isAdmin && reqStatus === 'COMPLETE') {
      html += '<button class="btn btn-icon btn-close-wo" title="Admin: ปิดงานในระบบและ Sheet W/O (CLOSED)" onclick="handlePmAdminDirectClose(\'' + r.UUID + '\')">' +
              '<i class="fas fa-folder-minus"></i></button>';
    } else if (isAdmin && (reqStatus === 'เสร็จสิ้น' || reqStatus === 'เสร็จสิ้น (Return to Service)')) {
      html += '<button class="btn btn-icon btn-wo-closed" title="ปิดงานแล้ว (CLOSED)" disabled>' +
              '<i class="fas fa-check-circle"></i></button>';
    }

    // 6. ปุ่ม Admin ลบ (แดง เหมือน CM)
    if (isAdmin) {
      html += '<button class="btn btn-icon btn-delete" title="ลบรายการ PM" onclick="showDeleteModal(\'' + r.UUID + '\', \'' +
              escapeHtml(r.RequestID || '') + '\')">' +
              '<i class="fas fa-trash"></i></button>';
    }

    html += '</div></td>';
    html += '</tr>';
  });

  tbody.innerHTML = html;
}

// === CREATE PM MODAL CONTROLLERS ===
function openCreatePmModal() {
  const modal = document.getElementById('pmCreateModal');
  if (!modal) return;
  const form = document.getElementById('pmCreateForm');
  if (form) form.reset();
  const today = new Date().toISOString().split('T')[0];
  const dateInput = document.getElementById('pmCreateTargetDate');
  if (dateInput) dateInput.value = today;
  const feedbackEl = document.getElementById('pmCreateEqFeedback');
  if (feedbackEl) feedbackEl.innerHTML = '';
  modal.style.display = 'flex';
}

function closeCreatePmModal() {
  const modal = document.getElementById('pmCreateModal');
  if (modal) modal.style.display = 'none';
}

function handlePmCodeInput(rawCode) {
  const code = (rawCode || '').toUpperCase().trim();
  const feedbackEl = document.getElementById('pmCreateEqFeedback');
  const nameEl = document.getElementById('pmCreateEqName');
  if (!feedbackEl) return;

  if (!code) {
    feedbackEl.innerHTML = '';
    return;
  }

  if (equipmentMasterList && equipmentMasterList.length > 0) {
    const item = equipmentMasterList.find(function(x) {
      return (x.gseNo || '').toUpperCase().trim() === code;
    });

    if (item) {
      feedbackEl.innerHTML = '<span style="color:#16A34A;"><i class="fas fa-check-circle"></i> ' + escapeHtml(item.description || item.gseNo) + '</span>';
      if (nameEl) nameEl.value = item.description || '';
    } else {
      feedbackEl.innerHTML = '<span style="color:#DC2626;"><i class="fas fa-exclamation-triangle"></i> ไม่พบรหัส ' + escapeHtml(code) + ' ในระบบ GSE MASTER</span>';
    }
  } else {
    loadEquipmentMaster(function() {
      handlePmCodeInput(rawCode);
    });
  }
}

function handleSavePmRequest() {
  const code = (document.getElementById('pmCreateEqCode').value || '').toUpperCase().trim();
  const name = document.getElementById('pmCreateEqName').value.trim();
  const checkLevel = document.getElementById('pmCreateCheckLevel').value;
  const targetDate = document.getElementById('pmCreateTargetDate').value;
  const notes = document.getElementById('pmCreateNotes').value.trim();

  if (!code) {
    showToast('กรุณาระบุรหัสอุปกรณ์ (Equipment Code)', 'error');
    return;
  }
  if (!targetDate) {
    showToast('กรุณาระบุกำหนดการเข้าตรวจ (Target Date)', 'error');
    return;
  }

  // Validate against GSE Master
  if (equipmentMasterList && equipmentMasterList.length > 0) {
    const valid = equipmentMasterList.some(function(x) {
      return (x.gseNo || '').toUpperCase().trim() === code;
    });
    if (!valid) {
      if (!confirm('คำเตือน: รหัสอุปกรณ์ "' + code + '" ไม่พบใน GSE MASTER คุณต้องการดำเนินการต่อหรือไม่?')) {
        return;
      }
    }
  }

  showLoading();
  const pmData = {
    equipmentCode: code,
    equipmentName: name || code,
    checkLevel: checkLevel,
    targetDate: targetDate,
    planDate: targetDate,
    notes: notes
  };

  const adminEmpId = currentUser ? currentUser.employeeId : '';

  google.script.run
    .withSuccessHandler(function(res) {
      hideLoading();
      if (res && res.success) {
        showToast(res.message || 'สร้างรายการ PM สำเร็จ', 'success');
        closeCreatePmModal();
        if (res.request) {
          if (!allRequests) allRequests = [];
          const existIdx = allRequests.findIndex(function(x) { return x.UUID === res.request.UUID; });
          if (existIdx >= 0) allRequests[existIdx] = res.request;
          else allRequests.unshift(res.request);

          recomputeAndUpdateCounts();
          if (currentDashboardTab === 'pm') {
            filterPmTable();
          } else {
            filterTable();
          }
        } else {
          loadDashboardData(true);
        }
      } else {
        showToast((res && res.message) ? res.message : 'เกิดข้อผิดพลาดในการสร้าง PM', 'error');
      }
    })
    .withFailureHandler(function(err) {
      hideLoading();
      showToast('เกิดข้อผิดพลาด: ' + (err.message || err), 'error');
    })
    .createPmRequest(pmData, adminEmpId);
}

// === BATCH IMPORT PM MODAL CONTROLLERS ===
function openImportPmModal() {
  const modal = document.getElementById('pmImportModal');
  if (!modal) return;
  document.getElementById('pmImportPasteArea').value = '';
  document.getElementById('pmImportPreviewWrapper').style.display = 'none';
  document.getElementById('pmImportPreviewTbody').innerHTML = '';
  document.getElementById('pmImportSummaryBadge').textContent = '';
  document.getElementById('btnExecuteBatchImport').disabled = true;

  const now = new Date();
  document.getElementById('pmImportMonth').value = (now.getMonth() + 1).toString();
  document.getElementById('pmImportYear').value = now.getFullYear().toString();

  modal.style.display = 'flex';
}

function closeImportPmModal() {
  const modal = document.getElementById('pmImportModal');
  if (modal) modal.style.display = 'none';
}

function handlePmImportPreview() {
  const rawText = document.getElementById('pmImportPasteArea').value.trim();
  if (!rawText) {
    showToast('กรุณาวางข้อมูลจาก Excel หรือระบุรายการที่ต้องการนำเข้า', 'warning');
    return;
  }

  const defaultMonth = document.getElementById('pmImportMonth').value;
  const defaultYear = document.getElementById('pmImportYear').value;

  const lines = rawText.split('\n');
  currentPmBatchImportData = [];

  let validCount = 0;
  let invalidCount = 0;
  let html = '';

  lines.forEach(function(line, idx) {
    const trimmed = line.trim();
    if (!trimmed) return;

    const parts = trimmed.split(/[\t,;]+/);
    const code = (parts[0] || '').toUpperCase().trim();
    let checkLvl = (parts[1] || 'Check A').trim();
    let targetDate = (parts[2] || '').trim();

    if (!targetDate) {
      targetDate = defaultYear + '-' + (defaultMonth.length === 1 ? '0' + defaultMonth : defaultMonth) + '-01';
    }

    let isValid = false;
    let eqDesc = '';
    if (equipmentMasterList && equipmentMasterList.length > 0) {
      const match = equipmentMasterList.find(function(x) {
        return (x.gseNo || '').toUpperCase().trim() === code;
      });
      if (match) {
        isValid = true;
        eqDesc = match.description || '';
      }
    } else {
      isValid = code.indexOf('TLM-') === 0;
    }

    if (isValid) validCount++;
    else invalidCount++;

    currentPmBatchImportData.push({
      equipmentCode: code,
      equipmentName: eqDesc || code,
      checkLevel: checkLvl,
      targetDate: targetDate,
      isValid: isValid
    });

    const statusBadge = isValid
      ? '<span style="color:#16A34A; font-weight:700;"><i class="fas fa-check-circle"></i> พร้อมนำเข้า</span>'
      : '<span style="color:#DC2626; font-weight:700;"><i class="fas fa-times-circle"></i> ไม่พบใน GSE MASTER</span>';

    html += '<tr style="background:' + (isValid ? '#FFFFFF' : '#FEF2F2') + ';">';
    html += '<td style="padding:6px 10px; text-align:center;">' + (currentPmBatchImportData.length) + '</td>';
    html += '<td style="padding:6px 10px; font-weight:700; color:' + (isValid ? '#1E293B' : '#DC2626') + ';">' + escapeHtml(code) + '</td>';
    html += '<td style="padding:6px 10px;">' + escapeHtml(eqDesc || '-') + '</td>';
    html += '<td style="padding:6px 10px; text-align:center;"><span class="pm-tc-badge">' + escapeHtml(checkLvl) + '</span></td>';
    html += '<td style="padding:6px 10px; text-align:center;">' + escapeHtml(targetDate) + '</td>';
    html += '<td style="padding:6px 10px; text-align:center;">' + statusBadge + '</td>';
    html += '</tr>';
  });

  const wrapper = document.getElementById('pmImportPreviewWrapper');
  wrapper.style.display = 'block';
  document.getElementById('pmImportPreviewTbody').innerHTML = html;

  const summary = document.getElementById('pmImportSummaryBadge');
  summary.innerHTML = '<span style="color:#16A34A;">พร้อมนำเข้า ' + validCount + ' รายการ</span>' +
    (invalidCount > 0 ? ' | <span style="color:#DC2626;">ไม่ผ่าน ' + invalidCount + ' รายการ</span>' : '');

  document.getElementById('btnExecuteBatchImport').disabled = (validCount === 0);
}

function executePmBatchImport() {
  const validList = currentPmBatchImportData.filter(function(x) { return x.isValid; });
  if (validList.length === 0) {
    showToast('ไม่มีรายการที่ผ่านการตรวจสอบ', 'error');
    return;
  }

  if (!confirm('ยืนยันการนำเข้าแผนงาน PM จำนวน ' + validList.length + ' รายการ?')) return;

  showLoading();
  const adminEmpId = currentUser ? currentUser.employeeId : '';

  google.script.run
    .withSuccessHandler(function(res) {
      hideLoading();
      if (res && res.success) {
        showToast(res.message || 'นำเข้าแผนงาน PM เรียบร้อยแล้ว', 'success');
        closeImportPmModal();
        loadDashboardData(true);
      } else {
        showToast((res && res.message) ? res.message : 'เกิดข้อผิดพลาดในการนำเข้า', 'error');
      }
    })
    .withFailureHandler(function(err) {
      hideLoading();
      showToast('เกิดข้อผิดพลาด: ' + (err.message || err), 'error');
    })
    .importPmMonthlyPlan(validList, adminEmpId);
}

// === DIGITAL TASK CARD MODAL CONTROLLERS & PRINT PREVIEW ===

let currentPmChecklistItems = [];
let pmPrintCurrentScale = 1.0;
const PM_PRINT_BASE_W = 794;

/**
 * 4. แมปปิ้งรถแทรกเตอร์ตามคำสั่งผู้ใช้งาน:
 * - 6 คัน CAMEL (TLM-TR-026 ถึง TLM-TR-031) -> TR-CAM-804-TLM
 * - 26 คัน TLD (TLM-TR-001, 006, 010, 018, 019, 025, 049 ถึง 068) -> TR-TLD-025-TLM
 */
function resolvePmModelKey(eqCode, eqName) {
  const norm = (eqCode || '').toUpperCase().trim();
  const desc = (eqName || '').toUpperCase().trim();
  const parts = norm.split('-');
  const gseType = parts.length >= 2 ? parts[1] : '';

  if (gseType === 'TR') {
    const trCamelCodes = [
      'TLM-TR-026', 'TLM-TR-027', 'TLM-TR-028',
      'TLM-TR-029', 'TLM-TR-030', 'TLM-TR-031'
    ];
    if (trCamelCodes.indexOf(norm) !== -1 || desc.indexOf('CAMEL') !== -1 || desc.indexOf('CAM') !== -1) {
      return 'TR-CAM-804-TLM';
    }
    return 'TR-TLD-025-TLM';
  } else if (gseType === 'PU') {
    if (desc.indexOf('VIGO') !== -1) return 'PU-TYT-VIG-TLM';
    if (desc.indexOf('CARRY') !== -1 || desc.indexOf('SUZUKI') !== -1) return 'PU-SZK-CAR-TLM';
    return 'PU-TYT-REV-TLM';
  } else if (gseType === 'VA') {
    return 'VA-TYT-COM-TLM';
  } else if (gseType === 'VP') {
    if (desc.indexOf('INNOVA') !== -1) return 'VP-TYT-INN-TLM';
    return 'VP-TYT-AVA-TLM';
  } else if (gseType === 'TT') {
    return 'TT-ISZ-4JJ-TLM';
  } else if (gseType === 'TB') {
    return 'TB-VNS-VNS-TLM';
  } else if (gseType === 'PS') {
    if (desc.indexOf('TLD') !== -1 || norm.indexOf('404') !== -1) return 'PS-TLD-404-TLM';
    return 'PS-SAM-SAM-TLM';
  } else if (gseType === 'BC') {
    return 'BC-SAM-SAM-TLM';
  } else if (gseType === 'PW') {
    if (desc.indexOf('CAM') !== -1) return 'PW-CAM-4KH-TLM';
    return 'PW-ISZ-4KH-TLM';
  } else if (gseType === 'WT') {
    return 'WT-ISZ-4KH-TLM';
  } else if (gseType === 'LV') {
    if (desc.indexOf('CAM') !== -1) return 'LV-CAM-4KH-TLM';
    return 'LV-ISZ-4KH-TLM';
  } else if (gseType === 'AC') {
    if (desc.indexOf('140') !== -1 || desc.indexOf('MAK') !== -1) return 'AC-MAK-140-TLM';
    return 'AC-TLD-804-TLM';
  } else if (gseType === 'AS') {
    if (desc.indexOf('600') !== -1 || desc.indexOf('TLD') !== -1) return 'AS-TLD-600-TLM';
    if (desc.indexOf('300') !== -1) return 'AS-MAK-300-TLM';
    return 'AS-MAK-180-TLM';
  } else if (gseType === 'GP') {
    if (desc.indexOf('090') !== -1 || norm.indexOf('090') !== -1) return 'GP-MAK-090-TLM';
    if (desc.indexOf('140') !== -1 || norm.indexOf('140') !== -1) return 'GP-MAK-140-TLM';
    if (desc.indexOf('409') !== -1 || norm.indexOf('409') !== -1) return 'GP-409-E-CUP-TLM';
    return 'GP-MAK-090-TLM';
  } else if (gseType === 'CB') {
    return 'CB-TLD-NBL-TLM';
  } else if (gseType === 'BU') {
    return 'BU-SCA-SCA-TLM';
  } else if (gseType === 'PB') {
    return 'PB-TLD-150-TLM';
  } else if (gseType === 'FL') {
    return 'FL-TYT-TYT-TLM';
  } else if (gseType === 'MP') {
    if (desc.indexOf('REN') !== -1) return 'MP-REN-PER-TLM';
    return 'MP-ISZ-PER-TLM';
  } else if (gseType === 'N2') {
    return 'N2-SAM-SAM-TLM';
  } else if (gseType === 'ES') {
    return 'ES-SAM-SAM-TLM';
  } else if (gseType === 'GE') {
    return 'GE-HYD-HYD-TLM';
  }

  // Fallback: หากลุ่มรหัสในแม่แบบ 36 รุ่น
  if (typeof PM_TASK_CARD_TEMPLATES !== 'undefined') {
    for (const k in PM_TASK_CARD_TEMPLATES) {
      if (PM_TASK_CARD_TEMPLATES[k].gseType === gseType) return k;
    }
  }
  return 'TR-TLD-025-TLM';
}

function normalizePmCheckLevel(checkLvl) {
  let clean = (checkLvl || 'A').toString().trim().toUpperCase();
  clean = clean.replace(/^PM\s+/, '').replace(/^CHECK\s+/, '').trim();
  if (clean.indexOf('C') !== -1 && clean !== 'CHECK') return 'C';
  if (clean.indexOf('B') !== -1) return 'B';
  return 'A';
}

function resolvePmTemplateKey(modelKey, checkLvl) {
  const lvl = normalizePmCheckLevel(checkLvl);
  if (modelKey === 'TR-CAM-804-TLM') {
    return 'TR-CAM-804-' + lvl + '-TLM';
  }
  if (modelKey === 'TR-TLD-025-TLM') {
    if (lvl === 'A') return 'TR-TLD-025-A-TLM';
    return 'TR-TLD-025-' + lvl + '-TLM';
  }
  const base = (modelKey || 'TR-TLD-025-TLM').replace(/-TLM$/, '');
  return base + '-' + lvl + '-TLM';
}

function getSerNoFromMaster(eqCode) {
  if (!eqCode || !equipmentMasterList || equipmentMasterList.length === 0) return '';
  const norm = eqCode.toString().toUpperCase().trim();
  const item = equipmentMasterList.find(function(x) {
    return (x.gseNo || '').toUpperCase().trim() === norm;
  });
  return item ? (item.serialNo || '') : '';
}

function openPmTaskCard(uuid) {
  const req = (allRequests || []).find(function(r) { return r.UUID === uuid; });
  if (!req) {
    showToast('ไม่พบข้อมูลรายการ PM ในระบบ', 'error');
    return;
  }

  currentActivePmRequest = req;
  const modal = document.getElementById('pmTaskCardModal');
  if (!modal) return;

  const checkLvl = req.PmCheckLevel || req.DamageAppearance || 'A';
  const cleanLvl = normalizePmCheckLevel(checkLvl);
  const modelKey = resolvePmModelKey(req.EquipmentCode, req.EquipmentName);

  document.getElementById('pmTcEqCode').value = req.EquipmentCode || '';
  document.getElementById('pmTcChaNo').value = 'N/A';
  document.getElementById('pmTcEngNo').value = 'N/A';

  let serNo = req.SerialNo || '';
  if (!serNo) serNo = getSerNoFromMaster(req.EquipmentCode);
  document.getElementById('pmTcSerNo').value = serNo || '-';

  document.getElementById('pmTcWoNo').value = req.WorkOrderNo || '-';
  document.getElementById('pmTcEqName').textContent = req.EquipmentName || '-';
  document.getElementById('pmTcTargetDate').textContent = req.InformDate || req.TargetDate || '-';
  document.getElementById('pmTcModelKey').textContent = modelKey + ' (Check ' + cleanLvl + ')';

  const checkBadge = document.getElementById('pmTcCheckBadge');
  if (checkBadge) checkBadge.textContent = 'CHECK ' + cleanLvl;

  const reqStatus = (req.Status || 'รอดำเนินการ').toString().trim();
  const statusBadge = document.getElementById('pmTcStatusBadge');
  if (statusBadge) {
    statusBadge.textContent = reqStatus;
    statusBadge.className = 'status-badge ' + getStatusClass(reqStatus);
  }

  let pmData = {};
  const rawJson = req.PmChecklistData || req.MaintenanceDetails;
  if (rawJson && typeof rawJson === 'string' && rawJson.trim().indexOf('{') === 0) {
    try { pmData = JSON.parse(rawJson); } catch(e) {}
  }

  document.getElementById('pmTcHrKm').value = pmData.hrMeter || pmData.hrKm || req.HrKm || '';

  const now = new Date();
  const todayDmy = formatDateDMY(now);
  document.getElementById('pmTcTechDate').value = pmData.completeDate || req.CompleteDate || todayDmy;

  renderPmToolRows(pmData.sectionB || []);
  renderPmConsumableRows(pmData.sectionC || []);
  renderPmChecklist(modelKey, cleanLvl, pmData.checklist || []);

  const defectFound = (pmData.defectFound || 'NO').toString().toUpperCase().trim();
  if (defectFound === 'YES') {
    document.getElementById('pmDefectRadioYes').checked = true;
  } else {
    document.getElementById('pmDefectRadioNo').checked = true;
  }
  document.getElementById('pmTcRectification').value = pmData.rectification || '';
  handlePmDefectRadioChange();

  renderPmMaterialRows(pmData.materials || []);
  populatePmTechnicianSelects(req, pmData);
  populatePmDualSignatures(req, pmData);
  configurePmActionButtons(req);

  modal.style.display = 'flex';
}

