// === SECTION D: CHECKLIST CONTROLLERS ===
function renderPmChecklist(modelKey, checkLvl, savedChecks) {
  const container = document.getElementById('pmTcChecklistContainer');
  if (!container) return;
  container.innerHTML = '';

  const cleanLvl = normalizePmCheckLevel(checkLvl);
  const allItems = [];

  // 1. ตรวจสอบจาก PM_TASK_CARD_TEMPLATES ก่อนเป็นลำดับแรก (มีรายละเอียดครบถ้วนทั้ง 36 รุ่น)
  if (typeof PM_TASK_CARD_TEMPLATES !== 'undefined' && PM_TASK_CARD_TEMPLATES[modelKey]) {
    const tpl = PM_TASK_CARD_TEMPLATES[modelKey];
    const chk = (tpl.checks && (tpl.checks[cleanLvl] || tpl.checks['A'] || Object.values(tpl.checks)[0])) || null;
    if (chk && chk.items && chk.items.length > 0) {
      chk.items.forEach(function(item) {
        allItems.push({
          no: item.no,
          desc: item.desc || item.text || ''
        });
      });
    }
  }

  // 2. หากยังไม่พบ ให้ดึงจาก PM_LAYOUT_DB
  if (allItems.length === 0) {
    const tplKey = resolvePmTemplateKey(modelKey, cleanLvl);
    const layoutPages = (typeof PM_LAYOUT_DB !== 'undefined' && (PM_LAYOUT_DB[tplKey] || PM_LAYOUT_DB['TR-TLD-025-A-TLM'])) || null;
    if (layoutPages) {
      layoutPages.forEach(function(p) {
        if (p.checklistItems && p.checklistItems.length > 0) {
          p.checklistItems.forEach(function(item) {
            allItems.push({
              no: item.itemNo,
              desc: item.text || ('Check item ' + item.itemNo)
            });
          });
        }
      });
    }
  }

  // 3. Fallback: รายการตรวจเช็คมาตรฐาน GSE 250-Hour Inspection เพื่อไม่ให้ช่องว่างเปล่าเด็ดขาด
  if (allItems.length === 0) {
    const standardItems = [
      { no: 1, desc: "250 HOURS GENERAL INSPECTION" },
      { no: 2, desc: "1. Check engine oil level and replenish if necessary" },
      { no: 3, desc: "2. Check coolant level and inspect radiator hoses" },
      { no: 4, desc: "3. Check battery terminals and cable connectors" },
      { no: 5, desc: "4. Check fan belts and alternator belt tension" },
      { no: 6, desc: "5. Check air filter condition, clean or replace if needed" },
      { no: 7, desc: "6. Check hydraulic fluid level and inspect for leaks" },
      { no: 8, desc: "7. Check brake fluid level and brake operation" },
      { no: 9, desc: "8. Check steering system and grease linkage joints" },
      { no: 10, desc: "9. Check tire condition and inflation pressure" },
      { no: 11, desc: "10. Check all lighting (headlights, beacon, turn lamps)" },
      { no: 12, desc: "11. Inspect tow bar / hitch mechanism for wear" },
      { no: 13, desc: "12. Check fire extinguisher validity and mounting" },
      { no: 14, desc: "13. Drain water / sediment from fuel filter" },
      { no: 15, desc: "14. General greasing and lubrication of all nipples" }
    ];
    standardItems.forEach(function(it) { allItems.push(it); });
  }

  currentPmChecklistItems = allItems;
  const counterEl = document.getElementById('pmTcChecklistCounter');
  if (counterEl) counterEl.textContent = '(' + allItems.length + ' รายการย่อย)';

  const savedMap = {};
  if (savedChecks && Array.isArray(savedChecks)) {
    savedChecks.forEach(function(c) {
      if (typeof c === 'number') savedMap[c] = true;
      else if (c && c.no) savedMap[c.no] = (c.checked === true || c.status === 'PASS');
    });
  }

  let html = '';
  allItems.forEach(function(item) {
    const isChecked = savedMap[item.no] !== undefined ? savedMap[item.no] : true; // Default checked per user preference
    const descText = (item.desc || '').trim();
    const isBoldHeader = !descText ||
      /^\d+\s*HOURS/i.test(descText) ||
      /^[A-Z0-9\s\(\)&/\-]+$/.test(descText) && !/^\d+\.\s*/.test(descText);

    if (isBoldHeader) {
      html += '<div class="pm-chk-group-header"><i class="fas fa-folder-open"></i> ' + escapeHtml(descText) + '</div>';
    } else {
      const cleanDesc = descText.replace(/^\d+\.\s*/, '');
      html += '<label class="pm-chk-item-row" for="chkItem_' + item.no + '">' +
        '<input type="checkbox" id="chkItem_' + item.no + '" class="pm-chk-box" data-no="' + item.no + '" ' + (isChecked ? 'checked' : '') + '>' +
        '<span style="flex:1;"><b>' + item.no + '.</b> ' + escapeHtml(cleanDesc || descText) + '</span>' +
        '</label>';
    }
  });

  container.innerHTML = html;
}

function toggleAllPmChecklist(checked) {
  const boxes = document.querySelectorAll('.pm-chk-box');
  boxes.forEach(function(b) { b.checked = checked; });
}

// === SECTION E: DEFECT FOUND & RECTIFICATION ===
function handlePmDefectRadioChange() {
  const yesRadio = document.getElementById('pmDefectRadioYes');
  const reqStar = document.getElementById('pmRectificationReqStar');
  const rectText = document.getElementById('pmTcRectification');
  if (!yesRadio || !reqStar || !rectText) return;

  if (yesRadio.checked) {
    reqStar.style.display = 'inline';
    rectText.style.borderColor = '#DC2626';
    rectText.style.background = '#FEF2F2';
    rectText.focus();
  } else {
    reqStar.style.display = 'none';
    rectText.style.borderColor = '#CBD5E1';
    rectText.style.background = '#FFFFFF';
  }
}

