function handlePmAdminCloseJob() {
  if (!currentActivePmRequest) return;
  if (!confirm('ยืนยันให้ Admin ปิดงานในระบบและอัพเดตสถานะใน Sheet "บันทึกการเปิด W/O" เป็น CLOSED?')) return;
  const userEmpId = currentUser ? currentUser.employeeId : '';
  showLoading();

  google.script.run
    .withSuccessHandler(function(res) {
      hideLoading();
      if (res && res.success) {
        showToast(res.message || 'ปิดงานในระบบและ Sheet สำเร็จ', 'success');
        currentActivePmRequest.Status = 'เสร็จสิ้น';
        recomputeAndUpdateCounts();
        filterPmTable();
        closePmTaskCardModal();
      } else {
        showToast((res && res.message) ? res.message : 'เกิดข้อผิดพลาด', 'error');
      }
    })
    .withFailureHandler(function(err) {
      hideLoading();
      showToast('เกิดข้อผิดพลาด: ' + (err.message || err), 'error');
    })
    .closePmJobByAdmin(currentActivePmRequest.UUID, userEmpId);
}

function handlePmAdminDirectClose(uuid) {
  if (!confirm('ยืนยันให้ Admin ปิดงาน PM ในระบบและ Sheet เป็น CLOSED?')) return;
  const userEmpId = currentUser ? currentUser.employeeId : '';
  showLoading();

  google.script.run
    .withSuccessHandler(function(res) {
      hideLoading();
      if (res && res.success) {
        showToast(res.message || 'ปิดงานสำเร็จ', 'success');
        loadDashboardData(true);
      } else {
        showToast((res && res.message) ? res.message : 'เกิดข้อผิดพลาด', 'error');
      }
    })
    .withFailureHandler(function(err) {
      hideLoading();
      showToast('เกิดข้อผิดพลาด: ' + (err.message || err), 'error');
    })
    .closePmJobByAdmin(uuid, userEmpId);
}

// === MULTI-PAGE PRINT PREVIEW CONTROLLERS ===
function triggerPmPrintFromModal() {
  if (!currentActivePmRequest) return;
  const uuid = currentActivePmRequest.UUID;
  closePmTaskCardModal();
  showPmPrintPreview(uuid);
}

function openPmTaskCardAndPrint(uuid) {
  showPmPrintPreview(uuid);
}

function printCurrentPmTaskCard() {
  if (currentActivePmRequest) showPmPrintPreview(currentActivePmRequest.UUID);
}

/**
 * showPmPrintPreview: สร้างเอกสาร A4 หลายหน้าครบถ้วนเหมือน PDF จริง 100%
 */
function showPmPrintPreview(uuid) {
  const req = (allRequests || []).find(function(r) { return r.UUID === uuid; });
  if (!req) {
    showToast('ไม่พบข้อมูลรายการ PM ในระบบ', 'error');
    return;
  }

  const checkLvl = req.PmCheckLevel || req.DamageAppearance || 'A';
  const cleanLvl = normalizePmCheckLevel(checkLvl);
  const modelKey = resolvePmModelKey(req.EquipmentCode, req.EquipmentName);
  let tplKey = resolvePmTemplateKey(modelKey, cleanLvl);

  let pagesB64 = (typeof PM_EMBEDDED_TEMPLATES !== 'undefined' && PM_EMBEDDED_TEMPLATES[tplKey]) ? PM_EMBEDDED_TEMPLATES[tplKey] : null;
  if (!pagesB64 && typeof PM_EMBEDDED_TEMPLATES !== 'undefined') {
    // Fallback template key based on equipment type
    if (modelKey.indexOf('GP') !== -1) {
      tplKey = 'GP-MAK-090-A-TLM';
    } else if (modelKey.indexOf('CAM') !== -1) {
      tplKey = 'TR-CAM-804-' + cleanLvl + '-TLM';
    } else {
      tplKey = 'TR-TLD-025-' + cleanLvl + '-TLM';
    }
    pagesB64 = PM_EMBEDDED_TEMPLATES[tplKey] || PM_EMBEDDED_TEMPLATES['TR-TLD-025-A-TLM'] || PM_EMBEDDED_TEMPLATES['TR-TLM-025-A-TLM'] || null;
  }

  if (!pagesB64) {
    showToast('ไม่พบแม่แบบพิมพ์สำหรับรายการนี้', 'error');
    return;
  }

  const numPages = pagesB64.length;

  let pmData = {};
  const rawJson = req.PmChecklistData || req.MaintenanceDetails;
  if (rawJson && typeof rawJson === 'string' && rawJson.trim().indexOf('{') === 0) {
    try { pmData = JSON.parse(rawJson); } catch(e) {}
  }

  let serNo = req.SerialNo || pmData.serialNo || '';
  if (!serNo) serNo = getSerNoFromMaster(req.EquipmentCode);

  const hrMeterVal = pmData.hrMeter || pmData.hrKm || req.HrKm || '';
  const woNoVal = req.WorkOrderNo || '';
  const techDateVal = pmData.completeDate || req.CompleteDate || req.InformDate || '';

  // Reported By names list
  const reportedByVal = (pmData.reportedBy || req.TechnicianName || req.ActionBy1 || '').toString().trim();

  // Verified By (Supervisor on top, Manager below)
  let verifiedByVal = pmData.verifiedBy || '';
  if (!verifiedByVal) {
    const supN = req.SupervisorName || '';
    const mgrN = req.ManagerName || '';
    if (supN && mgrN) verifiedByVal = supN + '\n' + mgrN;
    else if (supN) verifiedByVal = supN;
    else if (mgrN) verifiedByVal = mgrN;
  }
  const verifiedDateVal = pmData.verifiedDate || req.ManagerDate || req.SupervisorDate || '';

  const container = document.getElementById('pmPrintPagesContainer');
  if (!container) return;
  container.innerHTML = '';

  const layoutPages = (typeof PM_LAYOUT_DB !== 'undefined' && PM_LAYOUT_DB[tplKey]) ? PM_LAYOUT_DB[tplKey] : [];

  // Saved check status map
  const checkedMap = {};
  if (pmData.checklist && Array.isArray(pmData.checklist)) {
    pmData.checklist.forEach(function(c) {
      if (typeof c === 'number') checkedMap[c] = true;
      else if (c && c.no) checkedMap[c.no] = (c.checked === true);
    });
  } else {
    // Default all checked
    for (let i = 1; i <= 60; i++) checkedMap[i] = true;
  }

  // Iterate each page
  for (let pIdx = 0; pIdx < numPages; pIdx++) {
    const pageNum = pIdx + 1;
    const pageDiv = document.createElement('div');
    pageDiv.className = 'pm-print-page';
    pageDiv.id = 'pmPage_' + pageNum;

    // Background Image
    const bgImg = document.createElement('img');
    bgImg.className = 'pm-print-page-bg';
    bgImg.src = pagesB64[pIdx];
    pageDiv.appendChild(bgImg);

    // Overlay Container
    const overlay = document.createElement('div');
    overlay.className = 'pm-print-overlay';

    // === PAGE 1 OVERLAYS ===
    if (pageNum === 1) {
      // Header Fields
      overlay.innerHTML += '<div class="pm-print-field" style="left:7.4%; top:10.7%; font-weight:700;">' + escapeHtml(req.EquipmentCode || '') + '</div>';
      overlay.innerHTML += '<div class="pm-print-field" style="left:7.6%; top:15.3%; font-weight:600;">N/A</div>';
      overlay.innerHTML += '<div class="pm-print-field" style="left:18.4%; top:15.3%; font-weight:600;">N/A</div>';
      overlay.innerHTML += '<div class="pm-print-field" style="left:7.4%; top:20.0%; font-weight:700;">' + escapeHtml(serNo || '') + '</div>';
      overlay.innerHTML += '<div class="pm-print-field" style="left:22.1%; top:19.7%; font-weight:700;">' + escapeHtml(hrMeterVal || '') + '</div>';
      overlay.innerHTML += '<div class="pm-print-field" style="left:82.3%; top:15.3%; font-weight:700;">' + escapeHtml(woNoVal || '') + '</div>';

      // Section B: Tools (y = 368, 391, 414 pt)
      const tools = pmData.sectionB || [
        { ref: 'กล่องเครื่องมือ', desc: 'ชุดเครื่องมือช่างประจำตัว' },
        { ref: 'ตัวขันกรองเครื่อง', desc: 'ประแจขันกรองน้ำมันเครื่อง' }
      ];
      const yToolsPct = [43.7, 46.4, 49.2];
      tools.slice(0, 3).forEach(function(t, idx) {
        const topP = yToolsPct[idx];
        overlay.innerHTML += '<div class="pm-print-field" style="left:7.6%; top:' + topP + '%;">' + escapeHtml(t.ref || t.reference || '') + '</div>';
        overlay.innerHTML += '<div class="pm-print-field" style="left:35.3%; top:' + topP + '%;">' + escapeHtml(t.desc || t.description || '') + '</div>';
      });

      // Section C: Consumables (y = 490, 510, 530, 550 pt)
      const cons = pmData.sectionC || [
        { desc: 'กรองน้ำมันเครื่อง', spec: 'KL094' },
        { desc: 'กรองโซล่า', spec: 'KF267' }
      ];
      const yConsPct = [58.2, 60.6, 63.0, 65.3];
      cons.slice(0, 4).forEach(function(c, idx) {
        const topP = yConsPct[idx];
        overlay.innerHTML += '<div class="pm-print-field" style="left:7.6%; top:' + topP + '%;">' + escapeHtml(c.desc || c.description || '') + '</div>';
        overlay.innerHTML += '<div class="pm-print-field" style="left:50.4%; top:' + topP + '%;">' + escapeHtml(c.spec || c.specification || '') + '</div>';
      });

      // Signatures Page 1
      overlay.innerHTML += '<div class="pm-print-field" style="left:7.6%; top:86.1%;">' + escapeHtml(techDateVal || '') + '</div>';
      overlay.innerHTML += '<div class="pm-print-field" style="left:21.0%; top:86.1%; line-height:1.35; white-space:pre-line;">' + escapeHtml(reportedByVal || '') + '</div>';
      if (verifiedDateVal) overlay.innerHTML += '<div class="pm-print-field" style="left:52.9%; top:86.1%;">' + escapeHtml(verifiedDateVal || '') + '</div>';
      if (verifiedByVal) overlay.innerHTML += '<div class="pm-print-field" style="left:66.4%; top:86.1%; line-height:1.35; white-space:pre-line;">' + escapeHtml(verifiedByVal || '') + '</div>';
    }

    // === CHECKLIST PAGES (Pages 2 to numPages - 1) ===
    if (pageNum > 1 && pageNum < numPages) {
      // Find layout for this page
      const pLayout = layoutPages.find(function(lp) { return lp.page === pageNum; });
      if (pLayout && pLayout.checklistItems) {
        pLayout.checklistItems.forEach(function(it) {
          if (checkedMap[it.itemNo] !== false) {
            const topPct = (it.y / 841.89) * 100;
            if (typeof PM_CHECK_ICON_B64 !== 'undefined') {
              overlay.innerHTML += '<img src="' + PM_CHECK_ICON_B64 + '" class="pm-print-check-icon" style="left:83.8%; top:' + topPct + '%;">';
            } else {
              overlay.innerHTML += '<div class="pm-print-field" style="left:83.8%; top:' + topPct + '%; font-weight:700; transform:translate(-50%,-50%);">✓</div>';
            }
          }
        });
      }
    }

    // === FINAL PAGE OVERLAYS ===
    if (pageNum === numPages) {
      const isDefectYes = (pmData.defectFound || 'NO').toString().toUpperCase().trim() === 'YES';
      if (typeof PM_CHECK_ICON_B64 !== 'undefined') {
        if (isDefectYes) {
          overlay.innerHTML += '<img src="' + PM_CHECK_ICON_B64 + '" class="pm-print-check-icon" style="left:19.1%; top:15.1%;">';
        } else {
          overlay.innerHTML += '<img src="' + PM_CHECK_ICON_B64 + '" class="pm-print-check-icon" style="left:32.6%; top:15.1%;">';
        }
      }

      // Rectification text on 3 dotted lines (y = 177, 200, 223 pt)
      const rectText = (pmData.rectification || '').toString().trim();
      if (rectText) {
        const line1 = rectText.substring(0, 65);
        const line2 = rectText.substring(65, 130);
        const line3 = rectText.substring(130, 195);
        if (line1) overlay.innerHTML += '<div class="pm-print-field" style="left:7.5%; top:21.0%;">' + escapeHtml(line1) + '</div>';
        if (line2) overlay.innerHTML += '<div class="pm-print-field" style="left:7.5%; top:23.7%;">' + escapeHtml(line2) + '</div>';
        if (line3) overlay.innerHTML += '<div class="pm-print-field" style="left:7.5%; top:26.5%;">' + escapeHtml(line3) + '</div>';
      }

      // Materials Table rows (y = 339, 365, 390, 416, 442 pt)
      const mats = pmData.materials || [];
      const yMatsPct = [40.3, 43.4, 46.3, 49.4, 52.5];
      mats.slice(0, 5).forEach(function(m, idx) {
        const topP = yMatsPct[idx];
        overlay.innerHTML += '<div class="pm-print-field" style="left:3.7%; top:' + topP + '%; text-align:center;">' + (m.no || (idx + 1)) + '</div>';
        overlay.innerHTML += '<div class="pm-print-field" style="left:7.5%; top:' + topP + '%;">' + escapeHtml(m.desc || m.name || '') + '</div>';
        overlay.innerHTML += '<div class="pm-print-field" style="left:33.6%; top:' + topP + '%;">' + escapeHtml(m.partNo || '') + '</div>';
        overlay.innerHTML += '<div class="pm-print-field" style="left:58.8%; top:' + topP + '%; text-align:center;">' + (m.qty || 1) + '</div>';
        overlay.innerHTML += '<div class="pm-print-field" style="left:68.9%; top:' + topP + '%;">' + escapeHtml(m.snBatch || m.typeModel || '') + '</div>';
      });

      // Signatures on Final Page
      overlay.innerHTML += '<div class="pm-print-field" style="left:7.6%; top:86.1%;">' + escapeHtml(techDateVal || '') + '</div>';
      overlay.innerHTML += '<div class="pm-print-field" style="left:21.0%; top:86.1%; line-height:1.35; white-space:pre-line;">' + escapeHtml(reportedByVal || '') + '</div>';
      if (verifiedDateVal) overlay.innerHTML += '<div class="pm-print-field" style="left:52.9%; top:86.1%;">' + escapeHtml(verifiedDateVal || '') + '</div>';
      if (verifiedByVal) overlay.innerHTML += '<div class="pm-print-field" style="left:66.4%; top:86.1%; line-height:1.35; white-space:pre-line;">' + escapeHtml(verifiedByVal || '') + '</div>';
    }

    pageDiv.appendChild(overlay);
    container.appendChild(pageDiv);
  }

  showPage('pmPrintPage');
  setTimeout(fitPmPrintToScreen, 60);
  setTimeout(fitPmPrintToScreen, 250);
}

// === ZOOM CONTROLLERS FOR PM PRINT ===
function setPmPrintScale(scale) {
  pmPrintCurrentScale = Math.min(2.0, Math.max(0.3, scale));
  const scaler = document.getElementById('pmPrintViewportScaler');
  if (scaler) {
    scaler.style.transform = 'scale(' + pmPrintCurrentScale + ')';
    scaler.style.transformOrigin = 'top center';
  }
  const badge = document.getElementById('pmPrintZoomBadge');
  if (badge) badge.textContent = Math.round(pmPrintCurrentScale * 100) + '%';
}

function adjustPmPrintZoom(delta) {
  setPmPrintScale(pmPrintCurrentScale + delta);
}

function resetPmPrintZoom() {
  setPmPrintScale(1.0);
}

function fitPmPrintToScreen() {
  const container = document.getElementById('pmPrintOuterContainer');
  if (!container) return;
  const winW = window.innerWidth || document.documentElement.clientWidth || 390;
  const containerW = container.clientWidth || winW;
  const padding = 16;
  const availW = Math.min(containerW, winW) - padding;
  if (availW <= 0) return;
  const targetScale = Math.min(1.0, availW / PM_PRINT_BASE_W);
  setPmPrintScale(Math.max(0.3, targetScale));
}




